insert into public.qcm_bank
  (bank_id, otr_number, module, chapter, context, star, corrected, stem, options, justification, sources)
values
(2424, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un homme de 50 ans, après avoir souffert à plusieurs reprises d''un torticolis, se plaint d''une douleur qui part de la fosse sus épineuse, et irradie de la face postérieure de l''épaule, au bord externe du bras et de l''avant bras, pour atteindre le pouce et l''index.', false, true, 'Le siège de la douleur permet un diagnostic topographique. Lequel ?', '[{"l":"A","t":"Nerf médian","c":false},{"l":"B","t":"Racine C5","c":false},{"l":"C","t":"Racine C6","c":true},{"l":"D","t":"Racine C7","c":false},{"l":"E","t":"Racine C8","c":false}]'::jsonb, 'Trajet typique : bord externe de l''avant bras et pouce.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2425, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un homme de 50 ans, après avoir souffert à plusieurs reprises d''un torticolis, se plaint d''une douleur qui part de la fosse sus épineuse, et irradie de la face postérieure de l''épaule, au bord externe du bras et de l''avant bras, pour atteindre le pouce et l''index.', false, true, 'L''examen pourrait montrer un déficit moteur :', '[{"l":"A","t":"Du biceps","c":true},{"l":"B","t":"Du long supinateur","c":true},{"l":"C","t":"Du triceps","c":false},{"l":"D","t":"Du court abducteur du pouce","c":false},{"l":"E","t":"Des interosseux","c":false}]'::jsonb, 'Triceps : C7, court abducteur du pouce et interosseux = C8, D1.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2426, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un homme de 50 ans, après avoir souffert à plusieurs reprises d''un torticolis, se plaint d''une douleur qui part de la fosse sus épineuse, et irradie de la face postérieure de l''épaule, au bord externe du bras et de l''avant bras, pour atteindre le pouce et l''index.', false, true, 'On recherchera aussi une modification (diminution ou abolition) :', '[{"l":"A","t":"Du réflexe bicipital","c":true},{"l":"B","t":"Du réflexe stylo-radial","c":true},{"l":"C","t":"Du réflexe cubito-pronateur","c":false},{"l":"D","t":"Du réflexe tricipital","c":false},{"l":"E","t":"Du réflexe palmo-mentonnier","c":false}]'::jsonb, 'Le bicipital est surtout dépendant de la racine C5.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2427, 35, 'Rhumatologie', 'Névralgie cervico-brachiale', 'Un homme de 50 ans, après avoir souffert à plusieurs reprises d''un torticolis, se plaint d''une douleur qui part de la fosse sus épineuse, et irradie de la face postérieure de l''épaule, au bord externe du bras et de l''avant bras, pour atteindre le pouce et l''index.', false, true, 'En fait, il n''y a ni déficit moteur ni modification des réflexes dans ce cas particulier. Les radiographies simples du rachis cervical montrent des images de cervicarthrose, banales à cet âge. Quel diagnostic vous paraît le plus probable ?', '[{"l":"A","t":"Syndrome du canal carpien","c":false},{"l":"B","t":"Névralgie cervico-brachiale vertébrale commune","c":true},{"l":"C","t":"Syndrome du canal de Guyon","c":false},{"l":"D","t":"Neurinome cervical","c":false},{"l":"E","t":"Syndrome du défilé costo-claviculaire","c":false}]'::jsonb, 'Le piège diagnostique classique de la NCB C6 est le syndrome du canal carpien dont la douleur peut remonter jusqu''au bras mais jamais dans la fosse sus-épineuse. Il existe fort heureusement des NCB non déficitaires.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2428, 30, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'Un diagnostic de myélome est porté chez un homme de 65 ans. Les examens pratiqués montrent : - V.S. = 120 1ère heure ; - électrophorèse du sérum à la : bande étroite identifiée comme IgG Kappa à l''immunoélectrophorèse. L''évaluation de la dysglobulinémie est de 42 g/l. Les autres Ig sont à : IgA 0,20 g/l et IgM 0,15 g/l - dans les urines, on trouve une protéinurie de Bence Jones : excrétion de chaîne Kappa à 4,3 g/24 heures - sur l''hémogramme on relève : hémoglobine = 81 g/l ; VGM = 88 fl, réticulocytes 12.10 exposant 9/l, leucocytes et plaquettes normaux - par ailleurs : créatininémie : 180 micromoI/l uricémie : 660 micromoI/l calcémie : 2.3 millimoI/l - le myélogramme montre une moelle riche avec une plasmocytose à 34 %.', false, true, 'Parmi les examens suivants, lequel ou lesquels vous paraît(paraissent) nécessaire(s) pour compléter les explorations ?', '[{"l":"A","t":"Scintigraphie osseuse","c":false},{"l":"B","t":"Radiographie du squelette","c":true},{"l":"C","t":"Lymphographie","c":false},{"l":"D","t":"Echographie abdominale","c":false},{"l":"E","t":"Ponction biopsie hépatique","c":false}]'::jsonb, 'Les radiographies du squelette complet sont indispensables au bilan initial et à la classification de ce myélome (classification de Durie et Salmon)', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2429, 30, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'Un diagnostic de myélome est porté chez un homme de 65 ans. Les examens pratiqués montrent : - V.S. = 120 1ère heure ; - électrophorèse du sérum à la : bande étroite identifiée comme IgG Kappa à l''immunoélectrophorèse. L''évaluation de la dysglobulinémie est de 42 g/l. Les autres Ig sont à : IgA 0,20 g/l et IgM 0,15 g/l - dans les urines, on trouve une protéinurie de Bence Jones : excrétion de chaîne Kappa à 4,3 g/24 heures - sur l''hémogramme on relève : hémoglobine = 81 g/l ; VGM = 88 fl, réticulocytes 12.10 exposant 9/l, leucocytes et plaquettes normaux - par ailleurs : créatininémie : 180 micromoI/l uricémie : 660 micromoI/l calcémie : 2.3 millimoI/l - le myélogramme montre une moelle riche avec une plasmocytose à 34 %.', false, true, 'Quel examen supplémentaire vous paraît le plus important pour expliquer l''anémie ?', '[{"l":"A","t":"Test de Coombs","c":false},{"l":"B","t":"Durée de vie des globules rouges","c":false},{"l":"C","t":"Mesure isotopique du volume globulaire total","c":false},{"l":"D","t":"Dosage du fer sérique","c":true},{"l":"E","t":"Recherche d''agglutinine irrégulière","c":false}]'::jsonb, 'Il s''agit d''une anémie isolée normocytaire et arégénérative, on peut rechercher une anémie ferriprive. Les autres causes les plus probables sont l''envahissement médullaire (le myélogramme n''est pas le strict reflet de la plasmocytose médullaire en raison de son caractère nodulaire) et l''anémie hémolytique (sécrétion d''une immunoglobuline anti-GR).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2430, 30, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'Un diagnostic de myélome est porté chez un homme de 65 ans. Les examens pratiqués montrent : - V.S. = 120 1ère heure ; - électrophorèse du sérum à la : bande étroite identifiée comme IgG Kappa à l''immunoélectrophorèse. L''évaluation de la dysglobulinémie est de 42 g/l. Les autres Ig sont à : IgA 0,20 g/l et IgM 0,15 g/l - dans les urines, on trouve une protéinurie de Bence Jones : excrétion de chaîne Kappa à 4,3 g/24 heures - sur l''hémogramme on relève : hémoglobine = 81 g/l ; VGM = 88 fl, réticulocytes 12.10 exposant 9/l, leucocytes et plaquettes normaux - par ailleurs : créatininémie : 180 micromoI/l uricémie : 660 micromoI/l calcémie : 2.3 millimoI/l - le myélogramme montre une moelle riche avec une plasmocytose à 34 %.', false, true, 'Parmi les critères suivants, lequel ou lesquels a(ont) une valeur pronostique ?', '[{"l":"A","t":"VS = 120","c":false},{"l":"B","t":"Uricémie à 660 micromoI/l","c":false},{"l":"C","t":"Hémoglobine : 81 g/l","c":true},{"l":"D","t":"Créatininémie : 180 micromoI/l","c":true},{"l":"E","t":"Protéinurie de Bence Jones : 4,3 g/24 h","c":true}]'::jsonb, 'Le pronostic d''un myélome est fonction : - de la masse tumorale reflétée par le taux de l''hémoglobine, de la calcémie, de l''immunoglobuline monoclonale et de la protéinurie de Bence Jones et par le nombre des lésions osseuses - de la cinétique de prolifération (bêta-2 microglobuline) - de l''insuffisance rénale - et enfin, du type immunologique du myélome et de la réponse au traitement.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2431, 30, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'Un diagnostic de myélome est porté chez un homme de 65 ans. Les examens pratiqués montrent : - V.S. = 120 1ère heure ; - électrophorèse du sérum à la : bande étroite identifiée comme IgG Kappa à l''immunoélectrophorèse. L''évaluation de la dysglobulinémie est de 42 g/l. Les autres Ig sont à : IgA 0,20 g/l et IgM 0,15 g/l - dans les urines, on trouve une protéinurie de Bence Jones : excrétion de chaîne Kappa à 4,3 g/24 heures - sur l''hémogramme on relève : hémoglobine = 81 g/l ; VGM = 88 fl, réticulocytes 12.10 exposant 9/l, leucocytes et plaquettes normaux - par ailleurs : créatininémie : 180 micromoI/l uricémie : 660 micromoI/l calcémie : 2.3 millimoI/l - le myélogramme montre une moelle riche avec une plasmocytose à 34 %.', false, true, 'Un traitement associant Alkéran® et Prednisone® est donné en cures mensuelles de 4 jours. Parmi les critères suivants, lequel vous paraît le plus valable pour juger de l''efficacité du traitement ?', '[{"l":"A","t":"Mesure de l''immunoglobuline monoclonale","c":true},{"l":"B","t":"Recalcification osseuse","c":false},{"l":"C","t":"Créatininémie","c":false},{"l":"D","t":"Dosage de l''hémoglobine sur l''hémogramme","c":false},{"l":"E","t":"Taux de plasmocytes dans la moelle osseuse","c":false}]'::jsonb, 'C et D sont intéressants mais le myélogramme est un très mauvais examen de surveillance (prolifération nodulaire).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2432, 30, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'Un diagnostic de myélome est porté chez un homme de 65 ans. Les examens pratiqués montrent : - V.S. = 120 1ère heure ; - électrophorèse du sérum à la : bande étroite identifiée comme IgG Kappa à l''immunoélectrophorèse. L''évaluation de la dysglobulinémie est de 42 g/l. Les autres Ig sont à : IgA 0,20 g/l et IgM 0,15 g/l - dans les urines, on trouve une protéinurie de Bence Jones : excrétion de chaîne Kappa à 4,3 g/24 heures - sur l''hémogramme on relève : hémoglobine = 81 g/l ; VGM = 88 fl, réticulocytes 12.10 exposant 9/l, leucocytes et plaquettes normaux - par ailleurs : créatininémie : 180 micromoI/l uricémie : 660 micromoI/l calcémie : 2.3 millimoI/l - le myélogramme montre une moelle riche avec une plasmocytose à 34 %.', false, true, 'Parmi les affirmations suivantes concernant l''évolution sous ce traitement proposé, laquelle ou lesquelles est(sont) exacte(s) ?', '[{"l":"A","t":"La guérison ne peut être attendue","c":false},{"l":"B","t":"Une réponse objective est attendue dans 2/3 des cas","c":false},{"l":"C","t":"Le traitement fait courir un risque de leucémie aiguë","c":true},{"l":"D","t":"La durée de survie médiane probable est de 10 ans","c":false},{"l":"E","t":"Le traitement augmente le risque d''amylose","c":false}]'::jsonb, 'La rémission complète est exceptionnelle mais possible, le taux de réponse est d''environ 50 % et la médiane de survie de 24 mois.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2433, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Madame X., 70 ans est traitée depuis 3 ans pour une insuffisance cardiaque par 1 comprimé de Digoxine® les jours pairs et 1 comprimé d''un diurétique thiazidique (Rénèse® : polythiazide) les jours impairs. Son état cardiaque est globalement stabilisé avec ce traitement. Cette malade vient consulter pour des douleurs des épaules et des cuisses avec gêne fonctionnelle importante, apparues progressivement il y a 3 mois. Ces douleurs sont permanentes mais plus marquées la nuit et la raideur est surtout matinale. Depuis 15 jours, existent des céphalées lancinantes et pulsatiles. L''amaigrissement est d''environ 10 kg en trois mois. L''examen clinique met en évidence une limitation douloureuse des mouvements des épaules et des hanches, mais la palpation de l''artère temporale gauche conduit à déceler un cordon indure et douloureux au toucher. Le reste de l''examen clinique est normal. La V.S. est à 100 mm à la 1ère heure. Il existe une anémie à 90 g/l d''hémoglobine, normochrome, normocytaire et arégénérative. Le bilan biologique est par ailleurs normal. Les radiographies du thorax, des épaules et des coxofémorales ne mettent en évidence aucune anomalie. Ainsi, chez cette malade atteinte d''une insuffisance cardiaque, l''on retient le diagnostic de pseudo-polyarthrite rhizomélique, associée à une maladie de Horton, confirmée par la biopsie de l''artère temporale gauche, Vous optez pour la corticothérapie à 1 mg/kg/jour.', false, true, 'En l''absence du traitement précité, quel est le risque classiquement redouté encouru par cette patiente ?', '[{"l":"A","t":"Accentuation des douleurs des épaules et des hanches","c":false},{"l":"B","t":"Surdité gauche","c":false},{"l":"C","t":"Oblitération artérielle iliaque","c":false},{"l":"D","t":"Amaurose","c":true},{"l":"E","t":"Hémiplégie droite","c":false}]'::jsonb, 'L''atteinte oculaire en général unilatérale, peut se bilatéraliser et entraîner une cécité complète. Son risque justifie la mise en route d''une corticothérapie urgente. Le mécanisme de l''atteinte oculaire peut correspondre à 3 types de lésions : l''oblitération aiguë de l''artère centrale de la rétine, l''oedème ischémique de la papille et la névrite optique rétrobu baire aiguë.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2434, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Madame X., 70 ans est traitée depuis 3 ans pour une insuffisance cardiaque par 1 comprimé de Digoxine® les jours pairs et 1 comprimé d''un diurétique thiazidique (Rénèse® : polythiazide) les jours impairs. Son état cardiaque est globalement stabilisé avec ce traitement. Cette malade vient consulter pour des douleurs des épaules et des cuisses avec gêne fonctionnelle importante, apparues progressivement il y a 3 mois. Ces douleurs sont permanentes mais plus marquées la nuit et la raideur est surtout matinale. Depuis 15 jours, existent des céphalées lancinantes et pulsatiles. L''amaigrissement est d''environ 10 kg en trois mois. L''examen clinique met en évidence une limitation douloureuse des mouvements des épaules et des hanches, mais la palpation de l''artère temporale gauche conduit à déceler un cordon indure et douloureux au toucher. Le reste de l''examen clinique est normal. La V.S. est à 100 mm à la 1ère heure. Il existe une anémie à 90 g/l d''hémoglobine, normochrome, normocytaire et arégénérative. Le bilan biologique est par ailleurs normal. Les radiographies du thorax, des épaules et des coxofémorales ne mettent en évidence aucune anomalie. Ainsi, chez cette malade atteinte d''une insuffisance cardiaque, l''on retient le diagnostic de pseudo-polyarthrite rhizomélique, associée à une maladie de Horton, confirmée par la biopsie de l''artère temporale gauche, Vous optez pour la corticothérapie à 1 mg/kg/jour.', false, true, 'Parmi les effets adverses suivants, quel(s) est(sont) celui(ceux) qu''il y a lieu de redouter chez cette patiente ainsi traitée ?', '[{"l":"A","t":"Protéinurie","c":false},{"l":"B","t":"Neutropénie","c":false},{"l":"C","t":"Hypokaliémie","c":true},{"l":"D","t":"Hyperglycémie","c":true},{"l":"E","t":"Augmentation du pH gastrique","c":false}]'::jsonb, 'Chez cette patiente, le régime associé à la corticothérapie devra être pauvre en sel, riche en potassium et en protides et pauvre en glucides.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2435, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un skieur fait une chute qui entraîne son bras en abduction rotation externe. La douleur est violente, il ressent un engourdissement du moignon de l''épaule : au cours du transfert au poste de secours, sa main enfle et se cyanose.', false, true, 'Le diagnostic de luxation antéro-interne de la scapulo-humérale est orienté par :', '[{"l":"A","t":"Il est possible de ramener le coude contre le corps","c":false},{"l":"B","t":"Il est impossible d''effectuer une rotation interne","c":true},{"l":"C","t":"Une rotation imprimée au coude ne se transmet pas à la tête humérale","c":false},{"l":"D","t":"Il y a un vide sous-acromial externe","c":true},{"l":"E","t":"Il y a précocement une importante ecchymose de la paroi thoracique","c":false}]'::jsonb, 'Connaissance.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2436, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un skieur fait une chute qui entraîne son bras en abduction rotation externe. La douleur est violente, il ressent un engourdissement du moignon de l''épaule : au cours du transfert au poste de secours, sa main enfle et se cyanose.', false, true, 'Vous retrouvez lors d''un examen systématique régional, une insensibilité à la piqûre au moignon de l''épaule, sur sa face externe. Vous évoquez alors une atteinte :', '[{"l":"A","t":"Du nerf sus-scapulaire","c":false},{"l":"B","t":"De la racine C7 du plexus brachial","c":false},{"l":"C","t":"Du nerf circonflexe","c":true},{"l":"D","t":"Du nerf musculo-cutané","c":false},{"l":"E","t":"De la branche superficielle du nerf spinal","c":false}]'::jsonb, 'Classique. L''attente du circonflexe doit être systématiquement recherchée lors d''une luxation de l''épaule. Elle associe à cette atteinte sensitive une paralysie du deltoïde, mais elle est difficile à mettre en évidence dans ce contexte traumatique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2437, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un skieur fait une chute qui entraîne son bras en abduction rotation externe. La douleur est violente, il ressent un engourdissement du moignon de l''épaule : au cours du transfert au poste de secours, sa main enfle et se cyanose.', false, true, 'La constatation d''un oedème avec cyanose fait rechercher :', '[{"l":"A","t":"Un arrachement du confluant veineux jugulo sous-clavier","c":false},{"l":"B","t":"Une compression de la veine céphalique","c":false},{"l":"C","t":"Une ischémie par rupture de l''artère axillaire","c":false},{"l":"D","t":"Une compression de la veine axillaire","c":true},{"l":"E","t":"Un réflexe vaso-constricteur distal","c":false}]'::jsonb, 'A et B - Sont bien sûr impossibles pour des raisons anatomiques.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2438, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un skieur fait une chute qui entraîne son bras en abduction rotation externe. La douleur est violente, il ressent un engourdissement du moignon de l''épaule : au cours du transfert au poste de secours, sa main enfle et se cyanose.', false, true, 'Quelle (quelles) association(s) lésionnelle(s) fréquente(s) allez-vous rechercher sur la radiographie de face de l''épaule droite ?', '[{"l":"A","t":"Une fracture de la clavicule","c":false},{"l":"B","t":"Une fracture du trochiter","c":true},{"l":"C","t":"Une fracture de l''acromion","c":false},{"l":"D","t":"Une fracture de la coracoïde","c":false},{"l":"E","t":"Une fracture de la glène de l''omoplate","c":true}]'::jsonb, 'A, C, D - Résultent plutôt d''impactions directes du moignon de l''épaule. E - Il s''agit classiquement d''une fracture du rebord antéro inférieur de la glène.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2439, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un skieur fait une chute qui entraîne son bras en abduction rotation externe. La douleur est violente, il ressent un engourdissement du moignon de l''épaule : au cours du transfert au poste de secours, sa main enfle et se cyanose.', false, true, 'Après réduction, vous conseillez :', '[{"l":"A","t":"Une semaine d''immobilisation","c":false},{"l":"B","t":"Trois semaines d''immobilisation","c":true},{"l":"C","t":"Une rééducation immédiate en rotation externe","c":false},{"l":"D","t":"Un plâtre thoraco-brachial pour un mois","c":false},{"l":"E","t":"Une écharpe coude au corps","c":true}]'::jsonb, 'Lors d''une première luxation traumatique, l''immobilisation a pour but, au moins théorique, d''obtenir la cicatrisation de la capsule. Le risque majeur est l''évolution vers la luxation récidivante.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2440, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un skieur fait une chute qui entraîne son bras en abduction rotation externe. La douleur est violente, il ressent un engourdissement du moignon de l''épaule : au cours du transfert au poste de secours, sa main enfle et se cyanose.', false, true, 'Ce blessé est suivi régulièrement. Au 4e mois, son deltoïde bien rééduqué se contracte très correctement, l''abduction active reste limitée à 15°, alors qu''en passif, elle atteint 90° sans difficulté. Quel diagnostic évoquez-vous ?', '[{"l":"A","t":"Une capsulite rétractile inférieure","c":false},{"l":"B","t":"Une rupture du tendon du sus-épineux","c":true},{"l":"C","t":"Une rupture du bourrelet glénoïdien","c":false},{"l":"D","t":"Une rupture du tendon du long biceps","c":false},{"l":"E","t":"Une séquelle de paralysie circonflexe","c":false}]'::jsonb, 'Il faut évoquer dans ce cas une rupture des muscles de la coiffe des rotateurs (dont B fait partie). La bonne contract bilité du deltoïde élimine E. L''abduction passive à 90° élimine A. C - Donne une épaule douloureuse instable.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2441, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 58 ans vient consulter pour des troubles de la marche avec une grande fatigue et des douleurs diffuses des membres inférieurs à la marche. Elle a beaucoup maigri et souffre d''une diarrhée. L''examen clinique révèle une cyphose dorsale mais le rachis est souple. Malgré une démarche en canard la mobilité des articulations des membres inférieurs est normale. La malade a des difficultés à se lever d''une chaise. La radiographie vertébrale et du bassin met en évidence une importante déminéralisation, avec aspect biconcave des corps vertébraux. Le diagnostic d''ostéomalacie est retenue. Elle a été traitée pendant 6 mois par 50 mg/24 h de fluorure de calcium.', false, true, 'Un diagnostic d''ostéomalacie a pu être porté sur le résultat de :', '[{"l":"A","t":"Une vitesse de sédimentation","c":false},{"l":"B","t":"Un dosage de la calcémie et de la phosphorémie,dans le sang et sur urines de 24 heures","c":true},{"l":"C","t":"Un dosage de la parathormone","c":false},{"l":"D","t":"Un test d''hypocalcémie à la calcitonine","c":false},{"l":"E","t":"Un dosage de la vitamine D","c":true}]'::jsonb, 'Une calcémie basse avec calciurie et 25-OH vitamine D effondrées signent le diagnostic d''ostéomalacie. Si la phosphorémie est effondrée, il faudra rechercher une hyperparathyroïdie associée.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2442, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 58 ans vient consulter pour des troubles de la marche avec une grande fatigue et des douleurs diffuses des membres inférieurs à la marche. Elle a beaucoup maigri et souffre d''une diarrhée. L''examen clinique révèle une cyphose dorsale mais le rachis est souple. Malgré une démarche en canard la mobilité des articulations des membres inférieurs est normale. La malade a des difficultés à se lever d''une chaise. La radiographie vertébrale et du bassin met en évidence une importante déminéralisation, avec aspect biconcave des corps vertébraux. Le diagnostic d''ostéomalacie est retenue. Elle a été traitée pendant 6 mois par 50 mg/24 h de fluorure de calcium.', false, true, 'Chez cette malade diarrhéique, on a évoqué le diagnostic de maladie coeliaque. Quels sont les 2 examens nécessaires au diagnostic ?', '[{"l":"A","t":"Une coloscopie","c":false},{"l":"B","t":"Un dosage de la vitamine D (250H D 3) circulante","c":false},{"l":"C","t":"Un test au D-Xylose","c":true},{"l":"D","t":"Une fibroscopie gastrique avec biopsie jéjunale","c":true},{"l":"E","t":"Une ponction biopsie du foie","c":false}]'::jsonb, 'QCM imprécise, le test au D-Xylose fera le diagnostic de malabsorption et la biopsie du grêle montrera l''atrophie villositaire totale. Il faut rechercher des anticorps anti-gliadine car la maladie coeliaque n''est pas la seule cause d''atrophie villositaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2443, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 58 ans vient consulter pour des troubles de la marche avec une grande fatigue et des douleurs diffuses des membres inférieurs à la marche. Elle a beaucoup maigri et souffre d''une diarrhée. L''examen clinique révèle une cyphose dorsale mais le rachis est souple. Malgré une démarche en canard la mobilité des articulations des membres inférieurs est normale. La malade a des difficultés à se lever d''une chaise. La radiographie vertébrale et du bassin met en évidence une importante déminéralisation, avec aspect biconcave des corps vertébraux. Le diagnostic d''ostéomalacie est retenue. Elle a été traitée pendant 6 mois par 50 mg/24 h de fluorure de calcium.', false, true, 'Parmi les situations suivantes, laquelle ou lesquelles peut(vent) se compliquer d''ostéomalacie ?', '[{"l":"A","t":"Ulcère gastrique traité par Cimétidine (Tagamet®)","c":false},{"l":"B","t":"Obstruction biliaire prolongée","c":true},{"l":"C","t":"Réaction étendue du grêle","c":true},{"l":"D","t":"Rectocolite hémorragique","c":false},{"l":"E","t":"Cancer colique","c":false}]'::jsonb, 'Il s''agit bien sûr de la résection étendue du grêle. La cimétidine donne exceptionnellement des hépatites qui ne sont pas cirrhogènes.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2444, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 58 ans vient consulter pour des troubles de la marche avec une grande fatigue et des douleurs diffuses des membres inférieurs à la marche. Elle a beaucoup maigri et souffre d''une diarrhée. L''examen clinique révèle une cyphose dorsale mais le rachis est souple. Malgré une démarche en canard la mobilité des articulations des membres inférieurs est normale. La malade a des difficultés à se lever d''une chaise. La radiographie vertébrale et du bassin met en évidence une importante déminéralisation, avec aspect biconcave des corps vertébraux. Le diagnostic d''ostéomalacie est retenue. Elle a été traitée pendant 6 mois par 50 mg/24 h de fluorure de calcium.', false, true, 'On peut attribuer à une affection néoplasique ou paranéoplasique :', '[{"l":"A","t":"L''amaigrissement","c":true},{"l":"B","t":"La diarrhée","c":true},{"l":"C","t":"Les douleurs osseuses","c":true},{"l":"D","t":"La calcémie à 28 mml/l, la phosphorémie à 0,7 mmol/l","c":true},{"l":"E","t":"Une hydroxyprolinurie normale","c":true}]'::jsonb, '(En tenant compte de la correction du taux de la calcémie de la proposition D). Le message de ce QCM est qu''il existe des ostéomalacies avec franche hypophosphorémie au cours des cancers avec métastases osseuses, des tumeurs mésenchymateuses, de la neurof bromatose, et d''autres causes rares.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2445, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 58 ans vient consulter pour des troubles de la marche avec une grande fatigue et des douleurs diffuses des membres inférieurs à la marche. Elle a beaucoup maigri et souffre d''une diarrhée. L''examen clinique révèle une cyphose dorsale mais le rachis est souple. Malgré une démarche en canard la mobilité des articulations des membres inférieurs est normale. La malade a des difficultés à se lever d''une chaise. La radiographie vertébrale et du bassin met en évidence une importante déminéralisation, avec aspect biconcave des corps vertébraux. Le diagnostic d''ostéomalacie est retenue. Elle a été traitée pendant 6 mois par 50 mg/24 h de fluorure de calcium.', false, true, 'Le fluor utilisé 6 mois chez cette patiente peut être responsable :', '[{"l":"A","t":"De l''ostéomalacie","c":true},{"l":"B","t":"De l''amaigrissement","c":false},{"l":"C","t":"De la diarrhée profuse","c":false},{"l":"D","t":"D''une calcémie à 2 mm/l","c":false},{"l":"E","t":"D''une phosphorémie à 0. 7 mml","c":false}]'::jsonb, 'QCM discutable car le fluor est partiellement responsable de l''ostéomalacie d''origine digestive et il peut donner une diarrhée généralement modérée.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2446, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 58 ans vient consulter pour des troubles de la marche avec une grande fatigue et des douleurs diffuses des membres inférieurs à la marche. Elle a beaucoup maigri et souffre d''une diarrhée. L''examen clinique révèle une cyphose dorsale mais le rachis est souple. Malgré une démarche en canard la mobilité des articulations des membres inférieurs est normale. La malade a des difficultés à se lever d''une chaise. La radiographie vertébrale et du bassin met en évidence une importante déminéralisation, avec aspect biconcave des corps vertébraux. Le diagnostic d''ostéomalacie est retenue. Elle a été traitée pendant 6 mois par 50 mg/24 h de fluorure de calcium.', false, true, 'Les fissures de Looser et Milkmann sont à rechercher préférentiellement chez cette malade sur :', '[{"l":"A","t":"Le 1/3 externe des clavicules","c":true},{"l":"B","t":"Le calcanéum","c":false},{"l":"C","t":"Les branches ilio-pubiennes","c":true},{"l":"D","t":"Les métacarpiens","c":false},{"l":"E","t":"La branche montante du maxillaire inférieur","c":false}]'::jsonb, 'Les sièges de prédilection des stries de Looser-Milkmann sont : le bassin (branches ischio-pubiennes et partie postérieure des ailes iliaques), les fémurs (col fémoral ou bord interne des diaphyses), les côtes, le bord externe des omoplates et les clavicules.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2447, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 58 ans vient consulter pour des troubles de la marche avec une grande fatigue et des douleurs diffuses des membres inférieurs à la marche. Elle a beaucoup maigri et souffre d''une diarrhée. L''examen clinique révèle une cyphose dorsale mais le rachis est souple. Malgré une démarche en canard la mobilité des articulations des membres inférieurs est normale. La malade a des difficultés à se lever d''une chaise. La radiographie vertébrale et du bassin met en évidence une importante déminéralisation, avec aspect biconcave des corps vertébraux. Le diagnostic d''ostéomalacie est retenue. Elle a été traitée pendant 6 mois par 50 mg/24 h de fluorure de calcium.', false, true, 'Une ostéomalacie par entéropathie au gluten étant retenue quel(s) traitement(s) va-t-on proposer ?', '[{"l":"A","t":"Calcium à fortes doses en perfusion intraveineuse","c":false},{"l":"B","t":"Phosphore 1 g par jour","c":false},{"l":"C","t":"Dédrogyl® 30 gouttes par jour","c":true},{"l":"D","t":"Régime sans gluten","c":true},{"l":"E","t":"Régime pauvre en graisses","c":false}]'::jsonb, 'Le traitement de l''ostéomalacie repose sur un apport vitamino-calcique à forte dose par voie orale en raison de la malabsoption (sous surveillance de la calcémie et de la calciurie). Le traitement de la maladie coeliaque est le régime sans gluten.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2448, 15, 'Traumatologie', 'Main', 'Un menuisier de 25 ans, droitier, fait une fausse manoeuvre et est blessé à la main droite par une scie circulaire. Vous êtes de garde et vous faites un premier bilan des lésions.', false, true, 'Une autre plaie traverse la paume à la base de l''index et du médius. Ceux-ci sont insensibles à la piqûre. Vous pensez à une atteinte :', '[{"l":"A","t":"De la branche profonde du nerf cubital","c":false},{"l":"B","t":"Des rameaux récurrents de la branche superficielle du nerf radial","c":false},{"l":"C","t":"Des nerfs interosseux et/ou de leurs branches collatérales","c":true},{"l":"D","t":"De l''arcade radio-cubitale superficielle","c":false},{"l":"E","t":"Aucune des réponses précédentes","c":false}]'::jsonb, 'Il s''agit des nerfs digitaux ou de leurs nerfs collatéraux (radial, cubital de chaque doigt).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2449, 15, 'Traumatologie', 'Main', 'Un menuisier de 25 ans, droitier, fait une fausse manoeuvre et est blessé à la main droite par une scie circulaire. Vous êtes de garde et vous faites un premier bilan des lésions.', false, true, 'Il y a une plaie en regard de P1 du médius et le médius à gardé une flexion de P2 sur P1 mais à perdu celle de P3 sur P2. Vous évoquez une section :', '[{"l":"A","t":"Du fléchisseur superficiel du médius","c":false},{"l":"B","t":"Du fléchisseur profond du médius","c":true},{"l":"C","t":"Des deux tendons fléchisseurs du médius","c":false},{"l":"D","t":"Des interosseux et lombricaux du médius","c":false},{"l":"E","t":"Des nerfs collatéraux","c":false}]'::jsonb, 'Connaissance. La section isolée du FCP en zone 2, (sur P1) où les 2 fléchisseurs sont présents, s''explique par la décussation du fléchisseur superficiel, qui de superficiel devient profond.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2450, 21, 'Rhumatologie', 'Arthrite septique', 'Une femme de 78 ans, pesant 80 kilos pour 1,68m, diabétique traitée par 2 comprimés quotidiens de Metformine (Glucophage®) consulte pour une douleur inguinale droite apparue spontanément 3 jours plus tôt, lancinante non calmée par le décubitus, d''intensité croissante, s''accompagnant d''une fébricule à 38° le matin, 38°5 le soir, sans frisson. Elle a pour antécédents une coxarthrose bilatérale peu invalidante et une crise unique de chondrocalcinose articulaire ayant-touché le poignet gauche 2 mois plus tôt, et ayant évolué favorablement sous anti-inflammatoires non stéroïdiens. L''examen clinique permet de noter : 1) L''existence d''une douleur à la pression de la tête fémorale droite. 2) Une limitation douloureuse des mouvements passifs de la hanche, par comparaison au côté opposé. Il n''y a ni tuméfaction locale, ni rougeur, ni exagération du lacis veineux. 3) Il existe à la plante du pied droit une excoriation cutanée que la patiente a provoquée en procédant à l''ablation énergique d''une hyperkératose banale. Les radiographies du bassin et de la hanche droite sont normales. La numération formule sanguine donne : 13,4 g d''hémoglobine/100 ml, 11 500 blancs dont 78 % de polynucléaires neutrophiles, 3 % d''éosinophiles, 19 % de Iymphocytes. La vitesse de sédimentation est à 34 mm à la première heure.', false, true, 'Quel(s) diagnostic(s) peu(ven)t être envisagé(s) ?', '[{"l":"A","t":"Crise de chondrocalcinose","c":true},{"l":"B","t":"Monoarthrite rhumatismale de début aigu","c":true},{"l":"C","t":"Poussée de coxarthrose","c":false},{"l":"D","t":"Arthrite septique","c":true},{"l":"E","t":"Ostéonécrose aseptique de la tête fémorale","c":false}]'::jsonb, 'C et E - Non : car il y a discordance entre l''intensité des signes cliniques (douleur, raideur) et la normalité de la radio. Enfin la patiente est fébrile. D - Doit être évoquée de principe en raison du terrain et de la plaie en ovale.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2451, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Une femme de 78 ans, pesant 80 kilos pour 1,68m, diabétique traitée par 2 comprimés quotidiens de Metformine (Glucophage®) consulte pour une douleur inguinale droite apparue spontanément 3 jours plus tôt, lancinante non calmée par le décubitus, d''intensité croissante, s''accompagnant d''une fébricule à 38° le matin, 38°5 le soir, sans frisson. Elle a pour antécédents une coxarthrose bilatérale peu invalidante et une crise unique de chondrocalcinose articulaire ayant-touché le poignet gauche 2 mois plus tôt, et ayant évolué favorablement sous anti-inflammatoires non stéroïdiens. L''examen clinique permet de noter : 1) L''existence d''une douleur à la pression de la tête fémorale droite. 2) Une limitation douloureuse des mouvements passifs de la hanche, par comparaison au côté opposé. Il n''y a ni tuméfaction locale, ni rougeur, ni exagération du lacis veineux. 3) Il existe à la plante du pied droit une excoriation cutanée que la patiente a provoquée en procédant à l''ablation énergique d''une hyperkératose banale. Les radiographies du bassin et de la hanche droite sont normales. La numération formule sanguine donne : 13,4 g d''hémoglobine/100 ml, 11 500 blancs dont 78 % de polynucléaires neutrophiles, 3 % d''éosinophiles, 19 % de Iymphocytes. La vitesse de sédimentation est à 34 mm à la première heure.', false, true, 'Parmi les examens suivants lequel vous semble utile pour préciser en urgence l''étiologie ?', '[{"l":"A","t":"Test au Latex et réaction de Waaler-Rose","c":false},{"l":"B","t":"Scintigraphie osseuse","c":false},{"l":"C","t":"Tomographies de l''articulation coxo-fémorale","c":false},{"l":"D","t":"Dosage de la calcémie","c":false},{"l":"E","t":"Ponction articulaire de la hanche droite","c":true}]'::jsonb, 'Sans équivoque, l''analyse du liquide articulaire fera le diagnostic.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2452, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Une femme de 78 ans, pesant 80 kilos pour 1,68m, diabétique traitée par 2 comprimés quotidiens de Metformine (Glucophage®) consulte pour une douleur inguinale droite apparue spontanément 3 jours plus tôt, lancinante non calmée par le décubitus, d''intensité croissante, s''accompagnant d''une fébricule à 38° le matin, 38°5 le soir, sans frisson. Elle a pour antécédents une coxarthrose bilatérale peu invalidante et une crise unique de chondrocalcinose articulaire ayant-touché le poignet gauche 2 mois plus tôt, et ayant évolué favorablement sous anti-inflammatoires non stéroïdiens. L''examen clinique permet de noter : 1) L''existence d''une douleur à la pression de la tête fémorale droite. 2) Une limitation douloureuse des mouvements passifs de la hanche, par comparaison au côté opposé. Il n''y a ni tuméfaction locale, ni rougeur, ni exagération du lacis veineux. 3) Il existe à la plante du pied droit une excoriation cutanée que la patiente a provoquée en procédant à l''ablation énergique d''une hyperkératose banale. Les radiographies du bassin et de la hanche droite sont normales. La numération formule sanguine donne : 13,4 g d''hémoglobine/100 ml, 11 500 blancs dont 78 % de polynucléaires neutrophiles, 3 % d''éosinophiles, 19 % de Iymphocytes. La vitesse de sédimentation est à 34 mm à la première heure.', false, true, 'Si la patiente vous demande un délai de réflexion de 48 heures, vous pouvez prescrire parmi les médicaments suivants :', '[{"l":"A","t":"Sels d''or","c":false},{"l":"B","t":"Antibiotiques anti-staphylococciques","c":false},{"l":"C","t":"Antibiotiques à large spectre","c":false},{"l":"D","t":"Antalgiques purs","c":true},{"l":"E","t":"Corticoïdes","c":false}]'::jsonb, 'On évitera particulièrement sur ce terrain une antibiothérapie à l''aveugle. Les corticoïdes bien entendus sont formellement contre-indiquées tant qu''une arthrite septique peut être suspectée.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2453, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Une femme de 78 ans, pesant 80 kilos pour 1,68m, diabétique traitée par 2 comprimés quotidiens de Metformine (Glucophage®) consulte pour une douleur inguinale droite apparue spontanément 3 jours plus tôt, lancinante non calmée par le décubitus, d''intensité croissante, s''accompagnant d''une fébricule à 38° le matin, 38°5 le soir, sans frisson. Elle a pour antécédents une coxarthrose bilatérale peu invalidante et une crise unique de chondrocalcinose articulaire ayant-touché le poignet gauche 2 mois plus tôt, et ayant évolué favorablement sous anti-inflammatoires non stéroïdiens. L''examen clinique permet de noter : 1) L''existence d''une douleur à la pression de la tête fémorale droite. 2) Une limitation douloureuse des mouvements passifs de la hanche, par comparaison au côté opposé. Il n''y a ni tuméfaction locale, ni rougeur, ni exagération du lacis veineux. 3) Il existe à la plante du pied droit une excoriation cutanée que la patiente a provoquée en procédant à l''ablation énergique d''une hyperkératose banale. Les radiographies du bassin et de la hanche droite sont normales. La numération formule sanguine donne : 13,4 g d''hémoglobine/100 ml, 11 500 blancs dont 78 % de polynucléaires neutrophiles, 3 % d''éosinophiles, 19 % de Iymphocytes. La vitesse de sédimentation est à 34 mm à la première heure.', false, true, 'Pour ce délai de 48 heures, quelle attitude faut-il recommander à la patiente ?', '[{"l":"A","t":"Faire de la rééducation en décharge","c":false},{"l":"B","t":"Faire de l''électrothérapie","c":false},{"l":"C","t":"Marcher avec des cannes anglaises sans appuyer le membre inférieur droit","c":true},{"l":"D","t":"Marcher à sa convenance","c":false},{"l":"E","t":"S''obliger à marcher","c":false}]'::jsonb, 'Bon sens ! Décharger la hanche atteinte.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2454, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 72 ans est adressée par son médecin traitant en milieu hospitalier pour altération récente de l''état général avec asthénie, amaigrissement d''environ 6 kg au cours des 3 derniers mois, état subfébrile quasi permanent (37,8° - 38° C) depuis plusieurs semaines, céphalées à type de brûlures superficielles prédominant dans la région temporale gauche et algies massétérines gauches déclenchées par la mastication. S''y associent quelques algies scapulaires bilatérales avec enraidissement douloureux de tout le rachis cervical, ainsi que des douleurs des hanches. A l''examen clinique, l''humeur est dépressive, l''état général apparaît altéré, le teint pâle. Discret souffle systolique apexien à l''auscultation cardiaque. Auscultation pleuro-pulmonaire normale. Pas de signe de phlébite. Pas d''oedème. T.A. 160/90. Absence d''adénopathie. Abdomen souple : pas d''hépatosplénomégalie. La mobilisation des épaules et des hanches est douloureuse. L''examen neurologique est normal. La pression de la région temporale gauche déclenche une douleur. Le revêtement cutanéo-muqueux est d''aspect normal. Les examens biologiques récemment effectués à la demande de son médecin avaient donné les résultats suivants : VS : 82/110, globules blancs : 12 400/mm3 dont 81 % de polynucléaires. Globules rouges : 3 300 000/mm3. Hémoglobine 8,7 %, VGM : 73 micron3; uricémie : 82 mg/l ; alpha-foeto-protéines 3 ng/ml (normale inférieure à 15 ng/ml) ; LDH : 200 micron/l (normale inférieure à 300), SGOT : 18 unités, SGPT : 22 unités, phosphatases alcalines : 240 unités, A.S.L.O. : 200 unités, fibrinogènémie : 7,8 g °/oo ; CRP : 60 mg °/oo (normale : 15 mg °/oo), Haptoglobinémie : 3,5 g °/oo (normale inférieure à 1, 5 9 °/oo)', false, true, 'Parmi les diagnostics évoqués, quel est celui que vous suggère ce tableau clinique et biologique ?', '[{"l":"A","t":"Thyroïdite subaiguë","c":false},{"l":"B","t":"Lupus érythémateux disséminé","c":false},{"l":"C","t":"Syndrome de Gougerot-sjِgren","c":false},{"l":"D","t":"Maladie de Horton","c":true},{"l":"E","t":"Sarcoïdose","c":false}]'::jsonb, 'Fortement évoquée par le siège des céphalées, les douleurs à la mastication, l''âge, l''altération de l''état général et le syndrome inflammatoire non spécifique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2455, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 72 ans est adressée par son médecin traitant en milieu hospitalier pour altération récente de l''état général avec asthénie, amaigrissement d''environ 6 kg au cours des 3 derniers mois, état subfébrile quasi permanent (37,8° - 38° C) depuis plusieurs semaines, céphalées à type de brûlures superficielles prédominant dans la région temporale gauche et algies massétérines gauches déclenchées par la mastication. S''y associent quelques algies scapulaires bilatérales avec enraidissement douloureux de tout le rachis cervical, ainsi que des douleurs des hanches. A l''examen clinique, l''humeur est dépressive, l''état général apparaît altéré, le teint pâle. Discret souffle systolique apexien à l''auscultation cardiaque. Auscultation pleuro-pulmonaire normale. Pas de signe de phlébite. Pas d''oedème. T.A. 160/90. Absence d''adénopathie. Abdomen souple : pas d''hépatosplénomégalie. La mobilisation des épaules et des hanches est douloureuse. L''examen neurologique est normal. La pression de la région temporale gauche déclenche une douleur. Le revêtement cutanéo-muqueux est d''aspect normal. Les examens biologiques récemment effectués à la demande de son médecin avaient donné les résultats suivants : VS : 82/110, globules blancs : 12 400/mm3 dont 81 % de polynucléaires. Globules rouges : 3 300 000/mm3. Hémoglobine 8,7 %, VGM : 73 micron3; uricémie : 82 mg/l ; alpha-foeto-protéines 3 ng/ml (normale inférieure à 15 ng/ml) ; LDH : 200 micron/l (normale inférieure à 300), SGOT : 18 unités, SGPT : 22 unités, phosphatases alcalines : 240 unités, A.S.L.O. : 200 unités, fibrinogènémie : 7,8 g °/oo ; CRP : 60 mg °/oo (normale : 15 mg °/oo), Haptoglobinémie : 3,5 g °/oo (normale inférieure à 1, 5 9 °/oo)', false, true, 'Parmi les complications suivantes, retenez celle qui est susceptible d''être en rapport avec cette affection ?', '[{"l":"A","t":"Greffe d''une infection opportuniste à Pneumocystis carinii","c":false},{"l":"B","t":"Constitution progressive d''une fibrose pulmonaire interstitielle","c":false},{"l":"C","t":"Survenue d''une cécité par obstruction de l''artère centrale de la rétine ou des artères ciliées postérieures","c":true},{"l":"D","t":"Apparition d''un lymphome malin","c":false},{"l":"E","t":"Développement d''une hypertension artérielle maligne","c":false}]'::jsonb, 'Très classique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2456, 9, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 72 ans est adressée par son médecin traitant en milieu hospitalier pour altération récente de l''état général avec asthénie, amaigrissement d''environ 6 kg au cours des 3 derniers mois, état subfébrile quasi permanent (37,8° - 38° C) depuis plusieurs semaines, céphalées à type de brûlures superficielles prédominant dans la région temporale gauche et algies massétérines gauches déclenchées par la mastication. S''y associent quelques algies scapulaires bilatérales avec enraidissement douloureux de tout le rachis cervical, ainsi que des douleurs des hanches. A l''examen clinique, l''humeur est dépressive, l''état général apparaît altéré, le teint pâle. Discret souffle systolique apexien à l''auscultation cardiaque. Auscultation pleuro-pulmonaire normale. Pas de signe de phlébite. Pas d''oedème. T.A. 160/90. Absence d''adénopathie. Abdomen souple : pas d''hépatosplénomégalie. La mobilisation des épaules et des hanches est douloureuse. L''examen neurologique est normal. La pression de la région temporale gauche déclenche une douleur. Le revêtement cutanéo-muqueux est d''aspect normal. Les examens biologiques récemment effectués à la demande de son médecin avaient donné les résultats suivants : VS : 82/110, globules blancs : 12 400/mm3 dont 81 % de polynucléaires. Globules rouges : 3 300 000/mm3. Hémoglobine 8,7 %, VGM : 73 micron3; uricémie : 82 mg/l ; alpha-foeto-protéines 3 ng/ml (normale inférieure à 15 ng/ml) ; LDH : 200 micron/l (normale inférieure à 300), SGOT : 18 unités, SGPT : 22 unités, phosphatases alcalines : 240 unités, A.S.L.O. : 200 unités, fibrinogènémie : 7,8 g °/oo ; CRP : 60 mg °/oo (normale : 15 mg °/oo), Haptoglobinémie : 3,5 g °/oo (normale inférieure à 1, 5 9 °/oo)', false, true, 'Parmi les examens complémentaires suivants, une aide au diagnostic peut provenir du résultat de :', '[{"l":"A","t":"Biopsie des glandes salivaires accessoires","c":false},{"l":"B","t":"Recherche de l''antigène d''histocompatibilité HLA-B27","c":false},{"l":"C","t":"Examen Doppler des artères céphaliques superficielles","c":false},{"l":"D","t":"Biopsies pulmonaires transbronchiques","c":false},{"l":"E","t":"Biopsie de l''artère temporale","c":true}]'::jsonb, 'Découle de la question précédente. Doit être faite de principe, et le plus rapidement possible, mais éventuellement après le début de la corticothérapie.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2457, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Une femme de 72 ans est adressée par son médecin traitant en milieu hospitalier pour altération récente de l''état général avec asthénie, amaigrissement d''environ 6 kg au cours des 3 derniers mois, état subfébrile quasi permanent (37,8° - 38° C) depuis plusieurs semaines, céphalées à type de brûlures superficielles prédominant dans la région temporale gauche et algies massétérines gauches déclenchées par la mastication. S''y associent quelques algies scapulaires bilatérales avec enraidissement douloureux de tout le rachis cervical, ainsi que des douleurs des hanches. A l''examen clinique, l''humeur est dépressive, l''état général apparaît altéré, le teint pâle. Discret souffle systolique apexien à l''auscultation cardiaque. Auscultation pleuro-pulmonaire normale. Pas de signe de phlébite. Pas d''oedème. T.A. 160/90. Absence d''adénopathie. Abdomen souple : pas d''hépatosplénomégalie. La mobilisation des épaules et des hanches est douloureuse. L''examen neurologique est normal. La pression de la région temporale gauche déclenche une douleur. Le revêtement cutanéo-muqueux est d''aspect normal. Les examens biologiques récemment effectués à la demande de son médecin avaient donné les résultats suivants : VS : 82/110, globules blancs : 12 400/mm3 dont 81 % de polynucléaires. Globules rouges : 3 300 000/mm3. Hémoglobine 8,7 %, VGM : 73 micron3; uricémie : 82 mg/l ; alpha-foeto-protéines 3 ng/ml (normale inférieure à 15 ng/ml) ; LDH : 200 micron/l (normale inférieure à 300), SGOT : 18 unités, SGPT : 22 unités, phosphatases alcalines : 240 unités, A.S.L.O. : 200 unités, fibrinogènémie : 7,8 g °/oo ; CRP : 60 mg °/oo (normale : 15 mg °/oo), Haptoglobinémie : 3,5 g °/oo (normale inférieure à 1, 5 9 °/oo)', false, true, 'Parmi les propositions thérapeutiques figurant ci-après, retenez celle qui vous paraît appropriée au cas de cette patiente ?', '[{"l":"A","t":"Corticothérapie : 0,5 à 1 mg/kg de Prednisone/jour puis réduction progressive ultérieure de la posologie","c":true},{"l":"B","t":"Antipaludéen de synthèse : Hydroxychloroquine 400 à 600 mg/jour","c":false},{"l":"C","t":"Immunosuppresseurs : cyclophosphamide 1 à 4 mg/kg/jour","c":false},{"l":"D","t":"Colchicine : 1 mg/jour","c":false},{"l":"E","t":"D-Pénicillamine : 600 mg/jour","c":false}]'::jsonb, 'Cette corticothérapie proposée est le traitement classique de la maladie de Horton. Elle est urgente ici, malgré l''existence d''ou syndrome dépressif, qu''elle risque d''aggraver. Sa posologie sera adaptée pour obtenir la normalisation de la VS.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2458, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Un homme de 55 ans, obèse, en pré-retraite, présente depuis plusieurs mois une douleur mécanique de l''aine, irradiant au genou, limitant à moins d''un kilomètre son périmètre de marche. Il monte difficilement les escaliers et boite à la fatigue.', false, true, 'Le diagnostic de coxarthrose primitive est compatible avec la constatation de :', '[{"l":"A","t":"Limitation des amplitudes en rotation externe","c":true},{"l":"B","t":"Adénopathie de l''aine","c":false},{"l":"C","t":"Flexum de hanche","c":true},{"l":"D","t":"Absence de tout antécédent traumatique ou médical de cette articulation","c":true},{"l":"E","t":"VS, CRP, formule sanguine, normales","c":true}]'::jsonb, 'La perte de mobilité se fait aux dépens de la RE (A), de l''abduction, et l''extension de hanche (C).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2459, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Un homme de 55 ans, obèse, en pré-retraite, présente depuis plusieurs mois une douleur mécanique de l''aine, irradiant au genou, limitant à moins d''un kilomètre son périmètre de marche. Il monte difficilement les escaliers et boite à la fatigue.', false, true, 'Quel est le meilleur examen complémentaire pour affirmer le diagnostic de coxarthrose ?', '[{"l":"A","t":"Arthrographie de hanche","c":false},{"l":"B","t":"Scanner","c":false},{"l":"C","t":"R.M.N.","c":false},{"l":"D","t":"Radiographies du bassin de face et centrées sur l''articulation de face et de faux profil","c":true},{"l":"E","t":"Scintigraphie au technetium","c":false}]'::jsonb, 'Sans commentaire. Toujours penser à rester simple.(et se rappeler en passant les quatre signes radiologiques de la coxarthrose).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2460, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Un homme de 55 ans, obèse, en pré-retraite, présente depuis plusieurs mois une douleur mécanique de l''aine, irradiant au genou, limitant à moins d''un kilomètre son périmètre de marche. Il monte difficilement les escaliers et boite à la fatigue.', false, true, 'Chez ce patient quelle est l''attitude thérapeutique immédiate ?', '[{"l":"A","t":"Arthroplastie totale","c":false},{"l":"B","t":"Ostéotomie fémorale pour retarder au maximum l''heure de l''arthroplastie","c":false},{"l":"C","t":"Cure d''amaigrissement, hygiène orthopédique de hanche, rééducation, traitement médical","c":true},{"l":"D","t":"Infiltration de corticoïdes dans la coxo-fémorale","c":false},{"l":"E","t":"Ostéotomie du bassin","c":false}]'::jsonb, 'Le traitement médical peut longtemps suffire, et permet de reculer l''heure de l''arthoplastie totale. D - Est contre-indiqué. E - Ne se conçoit que dans des indications très particulières, pour certaines coxarthroses secondaires à une dysplasie de hanche.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2461, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Un homme de 55 ans, obèse, en pré-retraite, présente depuis plusieurs mois une douleur mécanique de l''aine, irradiant au genou, limitant à moins d''un kilomètre son périmètre de marche. Il monte difficilement les escaliers et boite à la fatigue.', false, true, 'L''évolution peut se faire vers :', '[{"l":"A","t":"Stabilisation","c":true},{"l":"B","t":"Attitude vicieuse","c":true},{"l":"C","t":"Restitution ad integrum","c":false},{"l":"D","t":"Coxopathie destructrice","c":true},{"l":"E","t":"Luxation antérieure de la tête fémorale","c":false}]'::jsonb, '(E - Jusqu''où va-t-on vous induire en erreur !!!).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2462, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'Une femme de 70 ans, vivant seule chez elle, est retrouvée sur le sol dans sa cuisine par ses voisins 24 heures après une chute d''un escabeau. Elle est consciente mais déshydratée. Elle est incapable de se relever du fait d''une impotence fonctionnelle totale du membre inférieur droit. Celui-ci parait raccourci, en abduction et rotation externe. La température est de 38°5. Le médecin habituel de cette malade, appelé en urgence, demande son hospitalisation et note sur son certificat ses antécédents : varices volumineuses bilatérales, insuffisance respiratoire chronique, coxarthrose droite évoluée.', false, true, 'La décision thérapeutique devrait être logiquement :', '[{"l":"A","t":"Une abstention chirurgicale","c":false},{"l":"B","t":"Une ostéosynthèse par vis","c":false},{"l":"C","t":"Une ostéosynthèse par clous de Ender","c":false},{"l":"D","t":"Une prothèse totale","c":true},{"l":"E","t":"Une prothèse céphalique","c":false}]'::jsonb, 'A - Est devenue exceptionnelle (mortalité +++) car il y a peu de contre-indications à l''anesthésie péridurale. B - On évite les vis si la patiente est âgée, pour pouvoir la faire rapidement marcher avec appui (avec une prothèse : à la 48ème heure). D - La prothèse totale est justifié car il existe une coxarthrose. Sinon l''indication est celle d''une prothèse fémorale simple.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2463, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'Une femme de 70 ans, vivant seule chez elle, est retrouvée sur le sol dans sa cuisine par ses voisins 24 heures après une chute d''un escabeau. Elle est consciente mais déshydratée. Elle est incapable de se relever du fait d''une impotence fonctionnelle totale du membre inférieur droit. Celui-ci parait raccourci, en abduction et rotation externe. La température est de 38°5. Le médecin habituel de cette malade, appelé en urgence, demande son hospitalisation et note sur son certificat ses antécédents : varices volumineuses bilatérales, insuffisance respiratoire chronique, coxarthrose droite évoluée.', false, true, 'Si un acte est effectué, il paraît justifié d''envisager en post-opératoire :', '[{"l":"A","t":"Lutte anti-escarre","c":true},{"l":"B","t":"Kinésithérapie respiratoire","c":true},{"l":"C","t":"Traitement anticoagulant","c":true},{"l":"D","t":"Bandages élastiques des membres","c":true},{"l":"E","t":"Lever précoce","c":true}]'::jsonb, 'Ce sont les règles classiques.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2464, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'A la suite d''un effort de soulèvement d''une charge lourde, Mr X..., 35 ans ressent une douleur aiguë dans la région lombaire bloquant le mouvement. Il doit s''aliter et 12 heures plus tard apparaît une douleur du membre inférieur droit intéressant la fesse, la cuisse, la face externe de la jambe et atteignant le dos du pied. Le réflexe achilléen est conservé. On note un signe de Lasègue à 20 degrés. Ce patient n''a jamais souffert auparavant de lombalgies.', false, true, 'Devant ce tableau quel est votre diagnostic ?', '[{"l":"A","t":"Sciatique tronculaire","c":false},{"l":"B","t":"Lombo-radiculite L 4","c":false},{"l":"C","t":"Lombo-sciatique L 5","c":true},{"l":"D","t":"Lombo-sciatique S 1","c":false},{"l":"E","t":"Sciatique cordonale","c":false}]'::jsonb, 'Connaissance.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2465, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'A la suite d''un effort de soulèvement d''une charge lourde, Mr X..., 35 ans ressent une douleur aiguë dans la région lombaire bloquant le mouvement. Il doit s''aliter et 12 heures plus tard apparaît une douleur du membre inférieur droit intéressant la fesse, la cuisse, la face externe de la jambe et atteignant le dos du pied. Le réflexe achilléen est conservé. On note un signe de Lasègue à 20 degrés. Ce patient n''a jamais souffert auparavant de lombalgies.', false, true, 'A ce stade quels sont les 2 examens complémentaires utiles ?', '[{"l":"A","t":"Radiographie standard du bassin et du rachis lombaire","c":true},{"l":"B","t":"Scintigraphie osseuse","c":false},{"l":"C","t":"Electromyogramme","c":false},{"l":"D","t":"Vitesse de sédimentation","c":true},{"l":"E","t":"Tomographies du rachis lombaire","c":false}]'::jsonb, 'La radiographie recherchera une attitude antalgique, un pincement discal, et vérifiera systématiquement l''absence d''anomalie transitionnelle.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2466, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'A la suite d''un effort de soulèvement d''une charge lourde, Mr X..., 35 ans ressent une douleur aiguë dans la région lombaire bloquant le mouvement. Il doit s''aliter et 12 heures plus tard apparaît une douleur du membre inférieur droit intéressant la fesse, la cuisse, la face externe de la jambe et atteignant le dos du pied. Le réflexe achilléen est conservé. On note un signe de Lasègue à 20 degrés. Ce patient n''a jamais souffert auparavant de lombalgies.', false, true, 'Quelle mesure thérapeutique est essentielle pour obtenir une amélioration ?', '[{"l":"A","t":"Manipulations vertébrales","c":false},{"l":"B","t":"Corticothérapie","c":false},{"l":"C","t":"Gymnastique vertébrale précoce","c":false},{"l":"D","t":"Repos au lit strict","c":true},{"l":"E","t":"Vitamines B injectables","c":false}]'::jsonb, 'Sans commentaire. Fait partie intégrante, avec l''arrêt de travail, du traitement de la lombosciatique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2467, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'A la suite d''un effort de soulèvement d''une charge lourde, Mr X..., 35 ans ressent une douleur aiguë dans la région lombaire bloquant le mouvement. Il doit s''aliter et 12 heures plus tard apparaît une douleur du membre inférieur droit intéressant la fesse, la cuisse, la face externe de la jambe et atteignant le dos du pied. Le réflexe achilléen est conservé. On note un signe de Lasègue à 20 degrés. Ce patient n''a jamais souffert auparavant de lombalgies.', false, true, 'Si 15 jours de traitement médical n''améliorent pas la douleur, quels sont les deux examens complémentaires capable de reconnaître la lésion responsable ?', '[{"l":"A","t":"Myélographie opaque dorsale","c":false},{"l":"B","t":"Scanner X lombaire","c":true},{"l":"C","t":"Potentiels évoqués somesthésiques","c":false},{"l":"D","t":"Sacco-radiculographie","c":true},{"l":"E","t":"Examen cyto-chimique du LCR","c":false}]'::jsonb, 'Le scanner montre la hernie, son siège (para-médian, foraminal, latéral) et son niveau. La saccoradiculographie montre la compression du fourreau dural, sur le profil, et une éventuelle compression radiculaire sur les 3/4.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2468, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'A la suite d''un effort de soulèvement d''une charge lourde, Mr X..., 35 ans ressent une douleur aiguë dans la région lombaire bloquant le mouvement. Il doit s''aliter et 12 heures plus tard apparaît une douleur du membre inférieur droit intéressant la fesse, la cuisse, la face externe de la jambe et atteignant le dos du pied. Le réflexe achilléen est conservé. On note un signe de Lasègue à 20 degrés. Ce patient n''a jamais souffert auparavant de lombalgies.', false, true, 'Quelles sont les deux complications neurologiques motrices possibles ?', '[{"l":"A","t":"Paralysie de la loge antéro-externe de jambe","c":true},{"l":"B","t":"Paralysie de la loge postérieure de jambe","c":false},{"l":"C","t":"Paralysie du quadriceps","c":false},{"l":"D","t":"Syndrome de la queue de cheval","c":true},{"l":"E","t":"Syndrome de compression médullaire","c":false}]'::jsonb, 'B - Correspond à S1. C - Correspond au crural (L4). J''espère que personne ne tombe dans le piège de E, car on est à priori en L5 S1 !', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2469, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 80 ans vient en consultation en urgence pour une baisse brutale de l''acuité visuelle de l''oeil droit. Elle se plaint de céphalées et d''une altération de l''état général. L''examen ophtalmologique va révéler au fond d''oeil droit un oedème ischémique de la papille optique. L''examen de l''oeil gauche est normal. L''examen des artères temporales superficielles les montre indurées et non battantes, beaucoup plus grosses qu''habituellement. Vous posez le diagnostic de maladie de Horton très probable.', false, true, 'Les complications oculaires de la maladie de Horton comportent :', '[{"l":"A","t":"L''ischémie aiguë de la tête du nerf optique","c":true},{"l":"B","t":"L''oedème papillaire de stase","c":false},{"l":"C","t":"L''occlusion de l''artère centrale de la rétine","c":true},{"l":"D","t":"L''occlusion de la veine centrale de la rétine","c":false},{"l":"E","t":"L''occlusion des capillaires rétiniens","c":false}]'::jsonb, 'La maladie de Horton est une artérite à tropisme prédominant sur les branches de la carotide externe.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2470, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 80 ans vient en consultation en urgence pour une baisse brutale de l''acuité visuelle de l''oeil droit. Elle se plaint de céphalées et d''une altération de l''état général. L''examen ophtalmologique va révéler au fond d''oeil droit un oedème ischémique de la papille optique. L''examen de l''oeil gauche est normal. L''examen des artères temporales superficielles les montre indurées et non battantes, beaucoup plus grosses qu''habituellement. Vous posez le diagnostic de maladie de Horton très probable.', false, true, 'Quel(s) examen(s) complémentaire(s) ophtalmologique(s) demandez vous pour préciser votre diagnostic ?', '[{"l":"A","t":"Champ visuel Goldmann","c":true},{"l":"B","t":"Test de Lancaster","c":false},{"l":"C","t":"Angiographie en fluorescence","c":true},{"l":"D","t":"Fluorométrie du vitré","c":false},{"l":"E","t":"Electrorétinographie","c":false}]'::jsonb, 'Il permettent d''évaluer l''extension des lésions.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2471, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 80 ans vient en consultation en urgence pour une baisse brutale de l''acuité visuelle de l''oeil droit. Elle se plaint de céphalées et d''une altération de l''état général. L''examen ophtalmologique va révéler au fond d''oeil droit un oedème ischémique de la papille optique. L''examen de l''oeil gauche est normal. L''examen des artères temporales superficielles les montre indurées et non battantes, beaucoup plus grosses qu''habituellement. Vous posez le diagnostic de maladie de Horton très probable.', false, true, 'Quel examen faut-il demander en urgence ?', '[{"l":"A","t":"Numération Formule Sanguine","c":false},{"l":"B","t":"Vitesse de sédimentation","c":true},{"l":"C","t":"Glycémie","c":false},{"l":"D","t":"Cholestérolémie","c":false},{"l":"E","t":"Clearance de la créatinine","c":false}]'::jsonb, 'La vitesse de sédimentation est quasi-constament supérieure à 50 mm à la première heure et est très évocatrice dans ce contexte.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2472, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 80 ans vient en consultation en urgence pour une baisse brutale de l''acuité visuelle de l''oeil droit. Elle se plaint de céphalées et d''une altération de l''état général. L''examen ophtalmologique va révéler au fond d''oeil droit un oedème ischémique de la papille optique. L''examen de l''oeil gauche est normal. L''examen des artères temporales superficielles les montre indurées et non battantes, beaucoup plus grosses qu''habituellement. Vous posez le diagnostic de maladie de Horton très probable.', false, true, 'L''examen histopathologique de la biopsie d''artère temporale superficielle peut révéler une atteinte :', '[{"l":"A","t":"De l''intima","c":true},{"l":"B","t":"De la média","c":true},{"l":"C","t":"De l''adventice","c":true},{"l":"D","t":"De la limitante élastique interne","c":true},{"l":"E","t":"De la limitante élastique externe","c":true}]'::jsonb, 'Il s''agit d''une pan-artérite segmentaire pluri-focale.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2473, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 80 ans vient en consultation en urgence pour une baisse brutale de l''acuité visuelle de l''oeil droit. Elle se plaint de céphalées et d''une altération de l''état général. L''examen ophtalmologique va révéler au fond d''oeil droit un oedème ischémique de la papille optique. L''examen de l''oeil gauche est normal. L''examen des artères temporales superficielles les montre indurées et non battantes, beaucoup plus grosses qu''habituellement. Vous posez le diagnostic de maladie de Horton très probable.', false, true, 'Sans attendre ce résultat, le traitement d''urgence repose sur :', '[{"l":"A","t":"Les vasodilatateurs","c":false},{"l":"B","t":"Les anticoagulants","c":true},{"l":"C","t":"Les anti-agrégants plaquettaires","c":false},{"l":"D","t":"Les corticoïdes","c":true},{"l":"E","t":"Les antalgiques","c":false}]'::jsonb, 'Il existe une baisse de l''acuité visuelle. Le traitement est urgent et associe des corticoïdes à forte dose, en perfusion puis relayé par voie orale, et des anticoagulants.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2474, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 80 ans vient en consultation en urgence pour une baisse brutale de l''acuité visuelle de l''oeil droit. Elle se plaint de céphalées et d''une altération de l''état général. L''examen ophtalmologique va révéler au fond d''oeil droit un oedème ischémique de la papille optique. L''examen de l''oeil gauche est normal. L''examen des artères temporales superficielles les montre indurées et non battantes, beaucoup plus grosses qu''habituellement. Vous posez le diagnostic de maladie de Horton très probable.', false, true, 'A plus long terme, le traitement repose sur :', '[{"l":"A","t":"Les vasodilatateurs","c":false},{"l":"B","t":"Les anticoagulants","c":false},{"l":"C","t":"Les anti-agrégants plaquettaires","c":true},{"l":"D","t":"Les corticoïdes","c":true},{"l":"E","t":"Les antalgiques","c":false}]'::jsonb, 'La diminution des doses de corticoïdes sera très progressive et longue. Du fait des troubles visuels un traitement anti- aggrégant plaquettaire peut être maintenu.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2475, 20, 'Rhumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', 'Une femme de 50 ans, consulte pour une douleur de l''épaule survenant à l''effort pendant la journée, réveillant la patiente lors du décubitus latéral prolongé. Un récent bilan biologique est normal.', false, true, 'Une pathologie de coiffe des rotateurs se traduit par :', '[{"l":"A","t":"Amyotrophie du deltoïde","c":false},{"l":"B","t":"Arc douloureux dans l''abduction vers 60°","c":true},{"l":"C","t":"Ascension de l''épaule lors de l''abduction active","c":true},{"l":"D","t":"Décollement unilatéral de l''omoplate","c":false},{"l":"E","t":"Limitation globale des mouvements passifs de l''épaule","c":false}]'::jsonb, 'B - L''arc douloureux entre 30° et 90° d''abduction active est caractéristique. C - S''explique par l''attente probable du sus épineux, et du tendon du long biceps (coaptateur de la tête) souvent impliqué dans les lésions de la coiffe, bien que ce ne soit pas un rotateur.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2476, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 50 ans, consulte pour une douleur de l''épaule survenant à l''effort pendant la journée, réveillant la patiente lors du décubitus latéral prolongé. Un récent bilan biologique est normal.', false, true, 'Quel signe radiologique permet de détecter précocément une rupture de la coiffe des rotateurs ?', '[{"l":"A","t":"Déminéralisation hétérogène de la tête humérale","c":false},{"l":"B","t":"Calcification se projetant dans l''espace sous-acromial","c":false},{"l":"C","t":"Ascension de la tête humérale en abduction contre résistance","c":true},{"l":"D","t":"Trop bonne visualisation du trochiter","c":false},{"l":"E","t":"Subluxation inférieure de la tête humérale","c":false}]'::jsonb, 'Cette manoeuvre est la manoeuvre de Leclerc. B - Calcification siégeant au-dessus du trochiter, se voit fréquemment dans les tendinopathies de la coiffe, mais n''en signe pas la rupture. (E - Se voit dans une paralysie des muscles de l''épaule : atteinte des plexus brachial...)', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2477, 20, 'Rhumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', 'Une femme de 50 ans, consulte pour une douleur de l''épaule survenant à l''effort pendant la journée, réveillant la patiente lors du décubitus latéral prolongé. Un récent bilan biologique est normal.', false, true, 'Vous réalisez une arthrographie. Quel(s) signe(s) radiographique(s) témoigne(nt) d''une rupture de coiffe des rotateurs ?', '[{"l":"A","t":"Une rupture du récessus interne sous-scapulaire","c":false},{"l":"B","t":"Une fuite de produit de contraste dans la gouttière bicipitale","c":false},{"l":"C","t":"Une opacification de la bourse sous-acromio-deltoïdienne","c":true},{"l":"D","t":"Une disparition du récessus articulaire inférieur","c":false},{"l":"E","t":"Une déchirure du bourrelet glénoïdien","c":false}]'::jsonb, 'Signe la rupture des muscles de la coiffe, car leur insertion se fait sur le trochiter et le trochin. B - Ne pas confondre, signe une rupture du tendon du long biceps intra-articulaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2478, 20, 'Rhumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', 'Une femme de 50 ans, consulte pour une douleur de l''épaule survenant à l''effort pendant la journée, réveillant la patiente lors du décubitus latéral prolongé. Un récent bilan biologique est normal.', false, true, 'La patiente vous apprend que quelques mois plus tôt, elle a consulté un autre rhumatologue pour des douleurs scapulaires très importantes. Celui-ci aurait parlé "d''épaule aiguë hyperalgique" que désigne ce terme ?', '[{"l":"A","t":"Rupture franche de la coiffe des rotateurs","c":false},{"l":"B","t":"Bursite aiguë sous-deltoïdienne microcristalline","c":true},{"l":"C","t":"Fissure des bourrelets glénoïdiens","c":false},{"l":"D","t":"Arrachement trochitérien","c":false},{"l":"E","t":"Hémarthrose","c":false}]'::jsonb, 'Connaissance.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2479, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 50 ans, consulte pour une douleur de l''épaule survenant à l''effort pendant la journée, réveillant la patiente lors du décubitus latéral prolongé. Un récent bilan biologique est normal.', false, true, 'En faveur d''une lésion ancienne de rupture de coiffe des rotateurs, vous pouvez retrouver sur les radios standard :', '[{"l":"A","t":"Déminéralisation hétérogène de la tête humérale","c":false},{"l":"B","t":"Calcification se projetant dans l''espace sous-acromial","c":false},{"l":"C","t":"Ascension permanente de la tête humérale","c":true},{"l":"D","t":"Remaniement trochitérien avec condensation et structure hétérogène","c":true},{"l":"E","t":"Rupture du cintre scapulo-huméral","c":true}]'::jsonb, 'Voir question [351].', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2480, 7, 'Rhumatologie', 'Complication de l’immobilité et décubitus', 'Une femme de 50 ans, consulte pour une douleur de l''épaule survenant à l''effort pendant la journée, réveillant la patiente lors du décubitus latéral prolongé. Un récent bilan biologique est normal.', false, true, 'Vous proposez une thérapeutique médicale. Quelle est la modalité non acceptable ?', '[{"l":"A","t":"Anti-inflammatoires non stéroïdiens lors des poussées douloureuses","c":false},{"l":"B","t":"Infiltrations de dérivés cortisonés retard dans l''espace sous-acromio-deltoïdien","c":false},{"l":"C","t":"Mobilisation active de l''épaule en abduction","c":true},{"l":"D","t":"Rééducation dans les mouvements de décoaptation","c":false},{"l":"E","t":"Antalgiques simples en dehors des poussées douloureuses","c":false}]'::jsonb, 'Il faut au contraire mettre au repos au début les rotateurs.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2481, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Une jeune femme de 29 ans, enceinte de 8 mois, se plaint depuis 1 mois de douleurs de la hanche et de la cuisse droites survenant à la marche et calmées par le repos. Elles irradient sur la face antérieure de la cuisse jusqu''au genou. Sa mère et sa soeur ainée auraient été traitées pour un syndrome douloureux comparable. Tous les mouvements de la hanche sont douloureux mais les amplitudes sont normales. La palpation révèle un point douloureux inguinal et fessier. La fosse iliaque droite est souple et l''utérus gravide est mobile. Le signe de Lasègue droit est positif à 80°. L''état général est bon. La température est à 37°5.', false, true, 'Parmi les résultats des examens complémentaires systématiquement demandés. lequel ou lesquels vous paraissent pathologiques :', '[{"l":"A","t":"Radio de la hanche droite de face - angle de couverture de la tête : 5° - angle d''obliquité du toit : 45°","c":true},{"l":"B","t":"Radio de la hanche droite de profil - angle de couverture de la tête : 5°","c":true},{"l":"C","t":"Vitesse de conduction sensitive du nerf sciatique : ralentissement droit de 5 % par rapport au côté gauche","c":false},{"l":"D","t":"Analyse du liquide de ponction : 500 éléments/mm3","c":false},{"l":"E","t":"Angle d''inclinaison extrémité supérieure du fémur droit : 135°","c":false}]'::jsonb, 'A, B - Critères de coxométrie normale : angle de couverture externe (VCE) supérieur ou égale à 25°, antérieur (VCA) supérieur ou égale à 25° ; angle d''obiquité (HTE) dutoit inférieur ou égale à 10°. E - On parle de coxa valga au-delà de 140°.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2482, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Une jeune femme de 29 ans, enceinte de 8 mois, se plaint depuis 1 mois de douleurs de la hanche et de la cuisse droites survenant à la marche et calmées par le repos. Elles irradient sur la face antérieure de la cuisse jusqu''au genou. Sa mère et sa soeur ainée auraient été traitées pour un syndrome douloureux comparable. Tous les mouvements de la hanche sont douloureux mais les amplitudes sont normales. La palpation révèle un point douloureux inguinal et fessier. La fosse iliaque droite est souple et l''utérus gravide est mobile. Le signe de Lasègue droit est positif à 80°. L''état général est bon. La température est à 37°5.', false, true, 'En fait, on aurait donc du se contenter de demander le ou les examens suivants :', '[{"l":"A","t":"Radio du bassin de face","c":true},{"l":"B","t":"Hanche droite face et profil","c":true},{"l":"C","t":"Faux profil de Lequesne","c":true},{"l":"D","t":"Ponction de hanche","c":false},{"l":"E","t":"EMG et mesure des vitesses de conduction du nerf crural","c":false}]'::jsonb, 'Ne pas oublier les clichés centrés dans tous les cas pour analyser une hanche. C - Est indispensable pour la mesure de l''angle VCA.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2483, 17, 'Rhumatologie', 'Maladies luxantes de la hanche', 'Une jeune femme de 29 ans, enceinte de 8 mois, se plaint depuis 1 mois de douleurs de la hanche et de la cuisse droites survenant à la marche et calmées par le repos. Elles irradient sur la face antérieure de la cuisse jusqu''au genou. Sa mère et sa soeur ainée auraient été traitées pour un syndrome douloureux comparable. Tous les mouvements de la hanche sont douloureux mais les amplitudes sont normales. La palpation révèle un point douloureux inguinal et fessier. La fosse iliaque droite est souple et l''utérus gravide est mobile. Le signe de Lasègue droit est positif à 80°. L''état général est bon. La température est à 37°5.', false, true, 'Quelle orientation diagnostique pouvez-vous en déduire ?', '[{"l":"A","t":"Sciatique gravidique à irradiation inguinale","c":false},{"l":"B","t":"Hernie crurale de la femme enceinte","c":false},{"l":"C","t":"Décompensation d''une dysplasie de hanche","c":true},{"l":"D","t":"Arthrite aiguë de hanche","c":false},{"l":"E","t":"Chondro-calcinose de la femme enceinte","c":false}]'::jsonb, 'La grossesse de 8 mois est responsable d''une surcharge mécanique. La dysplasie (ici noter de plus la notion familiale, prévalence féminine) était jusque là bien tolérée chez cette femme jeune.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2484, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Une jeune femme de 29 ans, enceinte de 8 mois, se plaint depuis 1 mois de douleurs de la hanche et de la cuisse droites survenant à la marche et calmées par le repos. Elles irradient sur la face antérieure de la cuisse jusqu''au genou. Sa mère et sa soeur ainée auraient été traitées pour un syndrome douloureux comparable. Tous les mouvements de la hanche sont douloureux mais les amplitudes sont normales. La palpation révèle un point douloureux inguinal et fessier. La fosse iliaque droite est souple et l''utérus gravide est mobile. Le signe de Lasègue droit est positif à 80°. L''état général est bon. La température est à 37°5.', false, true, 'Quelle conduite thérapeutique doit-on adopter ?', '[{"l":"A","t":"Proposer des antalgiques et un repos relatif jusqu''à la fin de la grossesse","c":true},{"l":"B","t":"Effectuer une infiltration épidurale de corticoïdes","c":false},{"l":"C","t":"Effectuer rapidement une ostéotomie de varisation de l''extrémité supérieure du fémur droit","c":false},{"l":"D","t":"Programmer la réalisation d''une intervention chirurgicale après l''accouchement","c":true},{"l":"E","t":"Effectuer rapidement une arthrotomie de la hanche droite","c":false}]'::jsonb, 'Puisqu''il s''agit d''une coxarthrose secondaire, probablement au début (29 ans, bien tolérée), on peut espérer stabiliser son évolution par un geste chirurgical (correction de la dysplasie).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2485, 36, 'Traumatologie', 'Traumatismes ligamentaires du genou', 'Un garçon de 18 ans consulte le lendemain d''un accident survenu lors d''un match de football. Il vous explique avoir ressenti, sans choc sur le genou, une vive douleur dans le genou, accompagnée d''une sensation fugace de déboîtement. Une tentative de reprise de jeu, quelques instants plus tard, a entraîné un accident identique. Le genou a gonflé en quelques minutes. L''examen révèle : - Un épanchement intra-articulaire avec choc rotulien - Une perte douloureuse de l''extension complète - Une limitation douloureuse de la flexion à 120° - Une sens bilité de l''interligne articulaire externe - L''absence de douleur sur le trajet du LLI - L''absence de laxité interne et externe en légère flexion - L''absence de signe de Smillie - L''absence de signe de Trillat Lachmann', false, true, 'Au terme de cet examen, vous concluez :', '[{"l":"A","t":"A la possibilité d''une lésion méniscale externe","c":true},{"l":"B","t":"Au diagnostic d''entorse bénigne puisque la stabilité du genou est conservée","c":false},{"l":"C","t":"A la possibilité d''une rupture isolée du ligament croisé antérieur","c":false},{"l":"D","t":"A la possibilité d''une luxation rotulienne spontanément réduite","c":false},{"l":"E","t":"A la possibilité d''une entorse grave du LLE","c":false}]'::jsonb, 'L''épanchement articulaire, le siège électif de la douleur sur l''interligne fémoro tibial externe, l''instabilité subjective avec absence de laxité à l''examen, sont très en faveur.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2486, 36, 'Traumatologie', 'Traumatismes ligamentaires du genou', 'Un garçon de 18 ans consulte le lendemain d''un accident survenu lors d''un match de football. Il vous explique avoir ressenti, sans choc sur le genou, une vive douleur dans le genou, accompagnée d''une sensation fugace de déboîtement. Une tentative de reprise de jeu, quelques instants plus tard, a entraîné un accident identique. Le genou a gonflé en quelques minutes. L''examen révèle : - Un épanchement intra-articulaire avec choc rotulien - Une perte douloureuse de l''extension complète - Une limitation douloureuse de la flexion à 120° - Une sens bilité de l''interligne articulaire externe - L''absence de douleur sur le trajet du LLI - L''absence de laxité interne et externe en légère flexion - L''absence de signe de Smillie - L''absence de signe de Trillat Lachmann', false, true, 'L''épanchement intra-articulaire actuel :', '[{"l":"A","t":"Justifie une ponction articulaire pour affirmer sa nature","c":false},{"l":"B","t":"Est certainement de nature hémorragique (hémarthrose) car il s''est rapidement constitué","c":true},{"l":"C","t":"Peut suffire pour expliquer la perte douloureuse de l''extension complète","c":true},{"l":"D","t":"Peut suffire pour expliquer la limitation de la flexion à 120°","c":true},{"l":"E","t":"Traduit l''existence d''une lésion intra-articulaire grave","c":false}]'::jsonb, 'Sans commentaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2487, 36, 'Traumatologie', 'Traumatismes ligamentaires du genou', 'Un garçon de 18 ans consulte le lendemain d''un accident survenu lors d''un match de football. Il vous explique avoir ressenti, sans choc sur le genou, une vive douleur dans le genou, accompagnée d''une sensation fugace de déboîtement. Une tentative de reprise de jeu, quelques instants plus tard, a entraîné un accident identique. Le genou a gonflé en quelques minutes. L''examen révèle : - Un épanchement intra-articulaire avec choc rotulien - Une perte douloureuse de l''extension complète - Une limitation douloureuse de la flexion à 120° - Une sens bilité de l''interligne articulaire externe - L''absence de douleur sur le trajet du LLI - L''absence de laxité interne et externe en légère flexion - L''absence de signe de Smillie - L''absence de signe de Trillat Lachmann', false, true, 'Il n''y avait pas de signe de Smillie, mais comment l''avez-vous recherché ?', '[{"l":"A","t":"En flexion du genou à 90° en exerçant une traction antérieure du tibia","c":false},{"l":"B","t":"En légère flexion et en luxant la rotule en dehors","c":true},{"l":"C","t":"En recherchant un point douloureux au bord interne de la rotule","c":false},{"l":"D","t":"A plat ventre genou fléchi à 600 en imprimant des mouvements de rotation au tibia","c":false},{"l":"E","t":"En appréciant la continuité de la rotule, du tendon rotulien et de la tubérosité tibiale antérieure","c":false}]'::jsonb, 'A - Est la recherche d''un tiroir antérieur. D - Est le grinding-test.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2488, 36, 'Traumatologie', 'Traumatismes ligamentaires du genou', 'Un garçon de 18 ans consulte le lendemain d''un accident survenu lors d''un match de football. Il vous explique avoir ressenti, sans choc sur le genou, une vive douleur dans le genou, accompagnée d''une sensation fugace de déboîtement. Une tentative de reprise de jeu, quelques instants plus tard, a entraîné un accident identique. Le genou a gonflé en quelques minutes. L''examen révèle : - Un épanchement intra-articulaire avec choc rotulien - Une perte douloureuse de l''extension complète - Une limitation douloureuse de la flexion à 120° - Une sens bilité de l''interligne articulaire externe - L''absence de douleur sur le trajet du LLI - L''absence de laxité interne et externe en légère flexion - L''absence de signe de Smillie - L''absence de signe de Trillat Lachmann', false, true, 'Votre recherche du tiroir antérieur à 90° de flexion à été gênée par la douleur et la difficulté d''obtenir un relâchement musculaire correct. Parmi les manoeuvres suivantes laquelle permet de tester plus sûrement le ligament croisé antérieur ?', '[{"l":"A","t":"La manoeuvre de Trillat Lachmann","c":true},{"l":"B","t":"La manoeuvre de Oudart","c":false},{"l":"C","t":"La recherche d''un ressaut rotatoire","c":false},{"l":"D","t":"La manoeuvre de Lasègue","c":false},{"l":"E","t":"La manoeuvre de Cabot","c":false}]'::jsonb, 'Note : le ressant rotatoire externe (ou jerk-test) est un bon signe d''atteinte du LCA, mais encore plus difficile à rechercher en absence de relâchement musculaire complet.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2489, 36, 'Traumatologie', 'Traumatismes ligamentaires du genou', 'Un garçon de 18 ans consulte le lendemain d''un accident survenu lors d''un match de football. Il vous explique avoir ressenti, sans choc sur le genou, une vive douleur dans le genou, accompagnée d''une sensation fugace de déboîtement. Une tentative de reprise de jeu, quelques instants plus tard, a entraîné un accident identique. Le genou a gonflé en quelques minutes. L''examen révèle : - Un épanchement intra-articulaire avec choc rotulien - Une perte douloureuse de l''extension complète - Une limitation douloureuse de la flexion à 120° - Une sens bilité de l''interligne articulaire externe - L''absence de douleur sur le trajet du LLI - L''absence de laxité interne et externe en légère flexion - L''absence de signe de Smillie - L''absence de signe de Trillat Lachmann', false, true, 'Vous faites préciser par l''interrogatoire, le mécanisme de l''accident. Parmi les mécanismes suivants, le(s)quel(s) aurai(en)t été susceptible(s) d''avoir entraîné une lésion isolée du ligament croisé antérieur ?', '[{"l":"A","t":"Valgus","c":false},{"l":"B","t":"Varus","c":false},{"l":"C","t":"Rotation externe du tibia sous le fémur","c":false},{"l":"D","t":"Rotation interne du tibia sous le fémur","c":true},{"l":"E","t":"Shoot dans le vide","c":true}]'::jsonb, 'D et E - Classiques. A et B - S''accompagnent de lésions des plans latéraux.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2490, 36, 'Traumatologie', 'Traumatismes ligamentaires du genou', 'Un garçon de 18 ans consulte le lendemain d''un accident survenu lors d''un match de football. Il vous explique avoir ressenti, sans choc sur le genou, une vive douleur dans le genou, accompagnée d''une sensation fugace de déboîtement. Une tentative de reprise de jeu, quelques instants plus tard, a entraîné un accident identique. Le genou a gonflé en quelques minutes. L''examen révèle : - Un épanchement intra-articulaire avec choc rotulien - Une perte douloureuse de l''extension complète - Une limitation douloureuse de la flexion à 120° - Une sens bilité de l''interligne articulaire externe - L''absence de douleur sur le trajet du LLI - L''absence de laxité interne et externe en légère flexion - L''absence de signe de Smillie - L''absence de signe de Trillat Lachmann', false, true, 'Pour compléter votre bilan clinique, quelle est la première prescription à effectuer aux urgences ?', '[{"l":"A","t":"Une ponction articulaire","c":false},{"l":"B","t":"Une radiographie face et profil du genou et un défilé fémoro-patellaire à 30° de flexion","c":true},{"l":"C","t":"Une épreuve radiographique dynamique en varus-valgus","c":false},{"l":"D","t":"Une arthrographie","c":false},{"l":"E","t":"Une arthroscopie","c":false}]'::jsonb, 'Le bilan standard doit toujours être fait, afin d''éliminer une fracture (en particulier plateau tibial, épines tibiales = insertion des croisés) ou une dysplasie évidente de la rotule. Les autres examens seront pratiquées en fonction de l''orientation diagnostique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2491, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X..., 60 ans, vous à consulté pour des douleurs lombaires basses apparues progressivement depuis 3 mois, de rythme mécanique, sans irradiation dans les membres inférieurs, calmées par l''Aspirine. Les radiographies que vous avez fait effectuer ont montré un aspect anormal du corps vertébral de L4 qui apparait hétérogène, non tassé, avec une ostéocondensation à prédominance périphérique, sans atteinte de l''arc postérieur. Le diamètre antéro-postérieur de ce corps vertébral est, sur le cliché de profil, augmenté par rapport à celui des vertèbres sus et sous-jacentes. Vous avez porté le diagnostic de maladie de Paget.', false, true, 'Quel(s) argument(s) radiologique(s) vous a (ont) permis d''écarter le diagnostic de métastases osseuses condensantes ?', '[{"l":"A","t":"Atteinte isolée de la vertèbre L4","c":false},{"l":"B","t":"Augmentation du diamètre antéro-postérieur du corps vertébral","c":true},{"l":"C","t":"Aspect hétérogène de la trame osseuse","c":false},{"l":"D","t":"Prédominance périphérique des lésions d''ostéocondensation","c":true},{"l":"E","t":"Absence de tassement vertébral","c":false}]'::jsonb, 'L''aspect radiologique d''un os pagétique comprend une trame anarchique, une dédifférenciation cortico-médullaire, une hypertrophie et une déformation. Une vertèbre pagétique peut se tasser.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2492, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X..., 60 ans, vous à consulté pour des douleurs lombaires basses apparues progressivement depuis 3 mois, de rythme mécanique, sans irradiation dans les membres inférieurs, calmées par l''Aspirine. Les radiographies que vous avez fait effectuer ont montré un aspect anormal du corps vertébral de L4 qui apparait hétérogène, non tassé, avec une ostéocondensation à prédominance périphérique, sans atteinte de l''arc postérieur. Le diamètre antéro-postérieur de ce corps vertébral est, sur le cliché de profil, augmenté par rapport à celui des vertèbres sus et sous-jacentes. Vous avez porté le diagnostic de maladie de Paget.', false, true, 'Parmi les anomalies biologiques suivantes, la maladie de Paget peut expliquer :', '[{"l":"A","t":"Augmentation des phosphatases acides sériques","c":false},{"l":"B","t":"Augmentation des phosphatases alcalines sériques","c":true},{"l":"C","t":"Augmentation de la Gamma GT sérique","c":false},{"l":"D","t":"Hypophosphorémie","c":false},{"l":"E","t":"Hypergammaglobulinémie","c":false}]'::jsonb, 'Les phosphatases alcalines traduisent l''activité des ostéoblastes et l''hydroxyprolinurie celle des ostéoclastes.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2493, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X..., 60 ans, vous à consulté pour des douleurs lombaires basses apparues progressivement depuis 3 mois, de rythme mécanique, sans irradiation dans les membres inférieurs, calmées par l''Aspirine. Les radiographies que vous avez fait effectuer ont montré un aspect anormal du corps vertébral de L4 qui apparait hétérogène, non tassé, avec une ostéocondensation à prédominance périphérique, sans atteinte de l''arc postérieur. Le diamètre antéro-postérieur de ce corps vertébral est, sur le cliché de profil, augmenté par rapport à celui des vertèbres sus et sous-jacentes. Vous avez porté le diagnostic de maladie de Paget.', false, true, 'Une scintigraphie osseuse au pyrophosphate de technétium :', '[{"l":"A","t":"Montre une hyperfixation constante des lésions osseuses de la maladie de Paget","c":true},{"l":"B","t":"Permet d''apprécier l''extension de la maladie sur l''ensemble du squelette","c":true},{"l":"C","t":"Permet d''éliminer l''éventualité de métastases osseuses","c":false},{"l":"D","t":"Permet de juger de l''évolutivité des lésions osseuses de la maladie de Paget","c":false},{"l":"E","t":"Permet d''apprécier globalement l''état de la minéralisation squelettique","c":false}]'::jsonb, 'L''extension de la maladie est une notion fondamentale à connaître si l''on veut interprêter correctement les anomalies biologiques.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2494, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X..., 60 ans, vous à consulté pour des douleurs lombaires basses apparues progressivement depuis 3 mois, de rythme mécanique, sans irradiation dans les membres inférieurs, calmées par l''Aspirine. Les radiographies que vous avez fait effectuer ont montré un aspect anormal du corps vertébral de L4 qui apparait hétérogène, non tassé, avec une ostéocondensation à prédominance périphérique, sans atteinte de l''arc postérieur. Le diamètre antéro-postérieur de ce corps vertébral est, sur le cliché de profil, augmenté par rapport à celui des vertèbres sus et sous-jacentes. Vous avez porté le diagnostic de maladie de Paget.', false, true, 'Parmi les complications osseuses suivantes, vous devez envisager au cours de la maladie de Paget ?', '[{"l":"A","t":"Déformation des os longs","c":true},{"l":"B","t":"Stries de Looser - Milkmann","c":false},{"l":"C","t":"Fractures vraies des os longs","c":true},{"l":"D","t":"Platybasie de la base du crâne","c":true},{"l":"E","t":"Dégénérescence sarcomateuse","c":true}]'::jsonb, 'Les stries de Looser-Milkmann sont des images d''ostéomalacie.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2495, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X..., 60 ans, vous à consulté pour des douleurs lombaires basses apparues progressivement depuis 3 mois, de rythme mécanique, sans irradiation dans les membres inférieurs, calmées par l''Aspirine. Les radiographies que vous avez fait effectuer ont montré un aspect anormal du corps vertébral de L4 qui apparait hétérogène, non tassé, avec une ostéocondensation à prédominance périphérique, sans atteinte de l''arc postérieur. Le diamètre antéro-postérieur de ce corps vertébral est, sur le cliché de profil, augmenté par rapport à celui des vertèbres sus et sous-jacentes. Vous avez porté le diagnostic de maladie de Paget.', false, true, 'Toutes les complications neurologiques suivantes peuvent survenir au cours de la maladie de Paget, sauf une. Laquelle ?', '[{"l":"A","t":"Surdité","c":false},{"l":"B","t":"Anosmie","c":false},{"l":"C","t":"Compression médullaire","c":false},{"l":"D","t":"Polyradiculonévrite","c":true},{"l":"E","t":"Syndrome de la queue de cheval","c":false}]'::jsonb, 'Sans commentaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2496, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X..., 60 ans, vous à consulté pour des douleurs lombaires basses apparues progressivement depuis 3 mois, de rythme mécanique, sans irradiation dans les membres inférieurs, calmées par l''Aspirine. Les radiographies que vous avez fait effectuer ont montré un aspect anormal du corps vertébral de L4 qui apparait hétérogène, non tassé, avec une ostéocondensation à prédominance périphérique, sans atteinte de l''arc postérieur. Le diamètre antéro-postérieur de ce corps vertébral est, sur le cliché de profil, augmenté par rapport à celui des vertèbres sus et sous-jacentes. Vous avez porté le diagnostic de maladie de Paget.', false, true, 'L''évolution de la maladie de Paget peut être freinée par la prise de :', '[{"l":"A","t":"Anti-inflammatoires non stéroïdiens","c":false},{"l":"B","t":"Corticoïdes","c":false},{"l":"C","t":"Calcitonine","c":true},{"l":"D","t":"Diphosphonates","c":true},{"l":"E","t":"Fluorure de Sodium","c":false}]'::jsonb, 'Ce sont deux médicaments efficaces. Les diphosphonates, surtout ceux de 2ème génération, sont particulièrement intéressants du fait de leur action anti-ostéoclastique prolongée.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2497, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X..., 60 ans, vous à consulté pour des douleurs lombaires basses apparues progressivement depuis 3 mois, de rythme mécanique, sans irradiation dans les membres inférieurs, calmées par l''Aspirine. Les radiographies que vous avez fait effectuer ont montré un aspect anormal du corps vertébral de L4 qui apparait hétérogène, non tassé, avec une ostéocondensation à prédominance périphérique, sans atteinte de l''arc postérieur. Le diamètre antéro-postérieur de ce corps vertébral est, sur le cliché de profil, augmenté par rapport à celui des vertèbres sus et sous-jacentes. Vous avez porté le diagnostic de maladie de Paget.', false, true, 'Parmi les examens biologiques suivants, lequel ou lesquels est(sont) utile(s) pour la surveillance à court terme de l''efficacité du traitement ?', '[{"l":"A","t":"Clairance du phosphore","c":false},{"l":"B","t":"Taux sérique de la parathormone","c":false},{"l":"C","t":"Taux sérique des phosphatases alcalines","c":true},{"l":"D","t":"Vitesse de sédimentation globulaire","c":false},{"l":"E","t":"Taux de la calcémie","c":false}]'::jsonb, 'Seules les phosphatases alcalines et l''hydroxyprolinurie sont utilisées pour la surveillance d''un Paget. La VS est demandée en cas de douleur persistante.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2498, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 65 ans est hospitalisée pour des lombalgies hautes de début brutal, survenues à la suite d''un faux mouvement. Dans les antécédents, on note une hernie inguinale gauche opérée à l''âge de 55 ans. Elle a été ménopausée à l''âge de 48 ans. Les lombalgies sont mécaniques, sans fièvre, ni altération de l''état général. L''examen clinique retrouve une douleur exquise à la palpation de L2. L''examen neurologique est normal. Les radiographies du rachis montrent un aspect peigné et un tassement de L2. La vitesse de sédimentation est à 10 mm à la première heure ; calcémie : 2,30 mmol/l; phosphorémie : 1,15 mmol/l ; calciurie et phosphaturie normales ; Phosphatases alcalines : 143 UI/l (normale 105 UI/l).', false, true, 'Parmi les antécédents suivants, le(s)quel(s) est (sont) un argument en faveur d''une ostéoporose commune ?', '[{"l":"A","t":"Coliques néphrétiques","c":false},{"l":"B","t":"Absence de traitement hormonal substitutif à la ménopause","c":true},{"l":"C","t":"Prise de Dihydan® au long cours","c":false},{"l":"D","t":"Résection étendue du grêle","c":false},{"l":"E","t":"Corticothérapie au long cours","c":false}]'::jsonb, 'Des coliques néphrétiques feraient rechercher un hyperparathyroïdisme ; la prise de Dihydan® et la résection du grêle, une ostéomalacie ; et enfin, la corticothérapie est responsable d''une ostéoporose particulière.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2499, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 65 ans est hospitalisée pour des lombalgies hautes de début brutal, survenues à la suite d''un faux mouvement. Dans les antécédents, on note une hernie inguinale gauche opérée à l''âge de 55 ans. Elle a été ménopausée à l''âge de 48 ans. Les lombalgies sont mécaniques, sans fièvre, ni altération de l''état général. L''examen clinique retrouve une douleur exquise à la palpation de L2. L''examen neurologique est normal. Les radiographies du rachis montrent un aspect peigné et un tassement de L2. La vitesse de sédimentation est à 10 mm à la première heure ; calcémie : 2,30 mmol/l; phosphorémie : 1,15 mmol/l ; calciurie et phosphaturie normales ; Phosphatases alcalines : 143 UI/l (normale 105 UI/l).', false, true, 'Parmi les signes radiographiques suivants, le(s)quel(s) remet(tent) en cause ce diagnostic ?', '[{"l":"A","t":"Recul du mur postérieur de L2","c":true},{"l":"B","t":"Fissure de la diaphyse fémorale","c":true},{"l":"C","t":"Tassements de D8, L1, L4","c":false},{"l":"D","t":"Lacunes crâniennes","c":true},{"l":"E","t":"Résorption des houppes phalangiennes","c":true}]'::jsonb, 'A - Est en faveur d''un tassement métastatique. B - Un myélome. E - Un hyperparathyroïdisme.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2500, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 65 ans est hospitalisée pour des lombalgies hautes de début brutal, survenues à la suite d''un faux mouvement. Dans les antécédents, on note une hernie inguinale gauche opérée à l''âge de 55 ans. Elle a été ménopausée à l''âge de 48 ans. Les lombalgies sont mécaniques, sans fièvre, ni altération de l''état général. L''examen clinique retrouve une douleur exquise à la palpation de L2. L''examen neurologique est normal. Les radiographies du rachis montrent un aspect peigné et un tassement de L2. La vitesse de sédimentation est à 10 mm à la première heure ; calcémie : 2,30 mmol/l; phosphorémie : 1,15 mmol/l ; calciurie et phosphaturie normales ; Phosphatases alcalines : 143 UI/l (normale 105 UI/l).', false, true, 'Comment intégrez-vous dans cette histoire l''augmentation des phosphatases alcalines ?', '[{"l":"A","t":"Lithiase du cholédoque","c":false},{"l":"B","t":"Tassement vertébral récent","c":true},{"l":"C","t":"Maladie de Paget associée","c":false},{"l":"D","t":"Ostéomalacie","c":false},{"l":"E","t":"Cirrhose biliaire primitive","c":false}]'::jsonb, 'Comme après toute fracture récente, dans les jours suivants un tassement vertébral, on peut observer une élévation transitoire de la calciurie, des phosphatases alcalines et de l''hydroxyprolinurie.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2501, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 65 ans est hospitalisée pour des lombalgies hautes de début brutal, survenues à la suite d''un faux mouvement. Dans les antécédents, on note une hernie inguinale gauche opérée à l''âge de 55 ans. Elle a été ménopausée à l''âge de 48 ans. Les lombalgies sont mécaniques, sans fièvre, ni altération de l''état général. L''examen clinique retrouve une douleur exquise à la palpation de L2. L''examen neurologique est normal. Les radiographies du rachis montrent un aspect peigné et un tassement de L2. La vitesse de sédimentation est à 10 mm à la première heure ; calcémie : 2,30 mmol/l; phosphorémie : 1,15 mmol/l ; calciurie et phosphaturie normales ; Phosphatases alcalines : 143 UI/l (normale 105 UI/l).', false, true, 'Votre attitude thérapeutique comprendra un ou plusieurs des actes suivants :', '[{"l":"A","t":"Ostéosynthèse par vis et plaques","c":false},{"l":"B","t":"Repos allongé pendant les premiers jours","c":true},{"l":"C","t":"Antalgiques","c":true},{"l":"D","t":"Mise en route d''un traitement par fluorure de sodium 50mg/jour","c":true},{"l":"E","t":"Kinésithérapie active des muscles abdominaux et paravertébraux","c":false}]'::jsonb, 'Le fluorure de sodium doit être accompagné d''un traitement vitamino-calcique. la kinésithérapie para-vertébrale ne peut être entreprise qu''en phase indolore.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2502, 21, 'Rhumatologie', 'Arthrite septique', 'Un homme de 60 ans est hospitalisé pour une crise d''arthrite aiguë du genou droit. Il s''agit d''un hypertendu traité par un diurétique thiazidique et mal équilibré. Il est asthénique, a une soif intense alors qu''il n''est pas diabétique. Sa température est à 38° sans frisson. La ponction du liquide articulaire du genou ramène un liquide trouble contenant 8 000 éléments par mm3 à prédominance de polynucléaires (80 %). Il contient des cristaux de pyrophosphate de calcium et d''acide urique. Il n''y a pas de germe à l''examen direct. La NFS donne les résultats suivants : 14000 blancs, 70 % de polynucléaires, l''uricémie est à 500 micromol/l. La radiographie du genou droit face et profil montre une calcification méniscale et du contour des condyles fémoraux.', false, true, 'Quels éléments du cas présent permettent d''affirmer le diagnostic de chondrocalcinose ?', '[{"l":"A","t":"Radiographies des genoux","c":true},{"l":"B","t":"L''existence de cristaux de pyrophosphates de calcium à la ponction articulaire","c":true},{"l":"C","t":"L''hyperleucocytose sanguine","c":false},{"l":"D","t":"L''hypercytose du liquide articulaire","c":false},{"l":"E","t":"L''hyperuricémie","c":false}]'::jsonb, 'La radiographie des genoux isolément, ne permettrait pas chez un homme de 60 ans d''affirmer le diagnostic.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2503, 21, 'Rhumatologie', 'Arthrite septique', 'Un homme de 60 ans est hospitalisé pour une crise d''arthrite aiguë du genou droit. Il s''agit d''un hypertendu traité par un diurétique thiazidique et mal équilibré. Il est asthénique, a une soif intense alors qu''il n''est pas diabétique. Sa température est à 38° sans frisson. La ponction du liquide articulaire du genou ramène un liquide trouble contenant 8 000 éléments par mm3 à prédominance de polynucléaires (80 %). Il contient des cristaux de pyrophosphate de calcium et d''acide urique. Il n''y a pas de germe à l''examen direct. La NFS donne les résultats suivants : 14000 blancs, 70 % de polynucléaires, l''uricémie est à 500 micromol/l. La radiographie du genou droit face et profil montre une calcification méniscale et du contour des condyles fémoraux.', false, true, 'Dans la pathogénie de la crise articulaire actuelle de ce malade, quelles autres hypothèses diagnostiques peuvent être discutées dans ce cas ?', '[{"l":"A","t":"Une hémarthrose","c":false},{"l":"B","t":"La goutte","c":true},{"l":"C","t":"Une hydarthrose d''origine arthrosique (poussée congestive d''arthrose)","c":false},{"l":"D","t":"Une infection associée à la chondrocalcinose","c":true},{"l":"E","t":"Une lésion méniscale","c":false}]'::jsonb, 'Il existe des cristaux d''acide urique dans le liquide articulaire. Il faut récupérer la culture du liquide avant d''éliminer le diagnostic d''infection.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2504, 21, 'Rhumatologie', 'Arthrite septique', 'Un homme de 60 ans est hospitalisé pour une crise d''arthrite aiguë du genou droit. Il s''agit d''un hypertendu traité par un diurétique thiazidique et mal équilibré. Il est asthénique, a une soif intense alors qu''il n''est pas diabétique. Sa température est à 38° sans frisson. La ponction du liquide articulaire du genou ramène un liquide trouble contenant 8 000 éléments par mm3 à prédominance de polynucléaires (80 %). Il contient des cristaux de pyrophosphate de calcium et d''acide urique. Il n''y a pas de germe à l''examen direct. La NFS donne les résultats suivants : 14000 blancs, 70 % de polynucléaires, l''uricémie est à 500 micromol/l. La radiographie du genou droit face et profil montre une calcification méniscale et du contour des condyles fémoraux.', false, true, 'Parmi ces associations avec la chondrocalcinose, quelles sont celles qui peuvent être rencontrées ?', '[{"l":"A","t":"L''hémochromatose","c":true},{"l":"B","t":"L''hyperparathyroïdisme","c":true},{"l":"C","t":"L''ostéoporose","c":true},{"l":"D","t":"L''ostéomalacie","c":false},{"l":"E","t":"L''hypothyroïdie","c":true}]'::jsonb, 'Associations pas toujours significatives.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2505, 21, 'Rhumatologie', 'Arthrite septique', 'Un homme de 60 ans est hospitalisé pour une crise d''arthrite aiguë du genou droit. Il s''agit d''un hypertendu traité par un diurétique thiazidique et mal équilibré. Il est asthénique, a une soif intense alors qu''il n''est pas diabétique. Sa température est à 38° sans frisson. La ponction du liquide articulaire du genou ramène un liquide trouble contenant 8 000 éléments par mm3 à prédominance de polynucléaires (80 %). Il contient des cristaux de pyrophosphate de calcium et d''acide urique. Il n''y a pas de germe à l''examen direct. La NFS donne les résultats suivants : 14000 blancs, 70 % de polynucléaires, l''uricémie est à 500 micromol/l. La radiographie du genou droit face et profil montre une calcification méniscale et du contour des condyles fémoraux.', false, true, 'Parmi les hypothèses suivantes, quelle(s) est (sont) celle(s) qui peut (peuvent) être à l''origine de la chondrocalcinose ?', '[{"l":"A","t":"Une hyperthyroïdie","c":false},{"l":"B","t":"Un hyperparathyroïdisme","c":true},{"l":"C","t":"Un diabète insipide","c":false},{"l":"D","t":"Une septicémie","c":false},{"l":"E","t":"Une polyarthrite rhumatoïde","c":false}]'::jsonb, 'L''hémochromatose, l''hypomagnésémie et l''hypophosphatase sont également des causes de CCA. L''hypothyroïdie a été éliminée par les dernières études controlées.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2506, 21, 'Rhumatologie', 'Arthrite septique', 'Un homme de 60 ans est hospitalisé pour une crise d''arthrite aiguë du genou droit. Il s''agit d''un hypertendu traité par un diurétique thiazidique et mal équilibré. Il est asthénique, a une soif intense alors qu''il n''est pas diabétique. Sa température est à 38° sans frisson. La ponction du liquide articulaire du genou ramène un liquide trouble contenant 8 000 éléments par mm3 à prédominance de polynucléaires (80 %). Il contient des cristaux de pyrophosphate de calcium et d''acide urique. Il n''y a pas de germe à l''examen direct. La NFS donne les résultats suivants : 14000 blancs, 70 % de polynucléaires, l''uricémie est à 500 micromol/l. La radiographie du genou droit face et profil montre une calcification méniscale et du contour des condyles fémoraux.', false, true, 'Parmi ces examens pour prouver un hyperparathyroïdisme, lesquels demandez-vous ?', '[{"l":"A","t":"Un bilan phosphocalcique sanguin et urinaire","c":true},{"l":"B","t":"Un ionogramme","c":false},{"l":"C","t":"Des radiographies des mains","c":true},{"l":"D","t":"Un dosage de la PTH","c":true},{"l":"E","t":"Une échographie de la région thyroïdienne","c":true}]'::jsonb, 'On recherche une hypercalcémie, une hypercalciurie et une hypophosphorémie, une résorption sous-périostée et des houppes phalangiennes, une PTH élevée et/ou inadaptée à la calcémie et enfin un adénome parathyroïdien.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2507, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Lors d''un match de rugby, un joueur de 24 ans, pilier droit est victime lors d''un placage d''un traumatisme de l''épaule droite entraînant une luxation antéro-interne. Sa réduction immédiate sur le terrain est réalisée puis une écharpe simple est mise en place pour 3 semaines coude au corps. Aucun bilan radiographique n''est réalisé. 1 an après, en se coiffant, il présente une récidive de la luxation antérieure qui fait l''objet d''une nouvelle réduction, et consulte ultérieurement.', false, true, 'Un bilan radiographique est réalisé pour le bilan de la luxation récidivante, il est utile de demander :', '[{"l":"A","t":"Face en double obliquité","c":true},{"l":"B","t":"Profil axillaire","c":false},{"l":"C","t":"Profil glénoïdien","c":true},{"l":"D","t":"Incidence de l''encoche de Strycker","c":false},{"l":"E","t":"Abduction contrariée","c":false}]'::jsonb, 'A - De face en RE du RI déroule la tête (et montre l''encoche en particulier) et le trochiter. C - Le profil glénoïdien recherche une fracture ou un écoulement de la glène. Le profil axillaire n''est pas indispensable. La radiographie en abduction contrariée (manoeuvre de Leclerc) recherche une rupture dynanique du cintre sous huméral, dans les pathologies de la coiffe.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2508, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Lors d''un match de rugby, un joueur de 24 ans, pilier droit est victime lors d''un placage d''un traumatisme de l''épaule droite entraînant une luxation antéro-interne. Sa réduction immédiate sur le terrain est réalisée puis une écharpe simple est mise en place pour 3 semaines coude au corps. Aucun bilan radiographique n''est réalisé. 1 an après, en se coiffant, il présente une récidive de la luxation antérieure qui fait l''objet d''une nouvelle réduction, et consulte ultérieurement.', false, true, 'Le bilan radiographique standard est normal, mais l''interrogatoire retrouve plusieurs épisodes de subluxation antérieure spontanément réductibles avec impression de ressaut laissant suspecter une atteinte du bourrelet glénoïdien Celle-ci sera affirmée par :', '[{"l":"A","t":"Arthrographie avec incidence de Bernageau","c":false},{"l":"B","t":"Echographie","c":false},{"l":"C","t":"IRM","c":true},{"l":"D","t":"Arthro-scanner","c":true},{"l":"E","t":"Tomographie","c":false}]'::jsonb, 'Ce sont les deux examens actuellement les plus performants pour objectiver l''atteinte du bourrelet et aussi la poche de décollement antéro-inférieur (lésion de Brocar-Hartmann).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2509, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Lors d''un match de rugby, un joueur de 24 ans, pilier droit est victime lors d''un placage d''un traumatisme de l''épaule droite entraînant une luxation antéro-interne. Sa réduction immédiate sur le terrain est réalisée puis une écharpe simple est mise en place pour 3 semaines coude au corps. Aucun bilan radiographique n''est réalisé. 1 an après, en se coiffant, il présente une récidive de la luxation antérieure qui fait l''objet d''une nouvelle réduction, et consulte ultérieurement.', false, true, 'Cet examen complémentaire montre une lésion du bourrelet avec décollement sous-capsulo périosté antérieur. Votre proposition thérapeutique doit être :', '[{"l":"A","t":"Rééducation de la sangle musculaire axée sur les rotateurs externes","c":false},{"l":"B","t":"Physiothérapie locale anti inflammatoire","c":false},{"l":"C","t":"Stabilisation antérieure chirurgicale","c":true},{"l":"D","t":"Acromioplastie chirurgicale","c":false},{"l":"E","t":"Abstention et surveillance","c":false}]'::jsonb, 'L''indication chirurgicale est licite chez ce sujet jeune, sportif, devant la récidive, pour les gestes de la vie courante, et devant l''existence de lésions objectives antéro-inférieures. D - Confusion avec le conflit sous-acromial et la pathologie de la coiffe. A - Proscrire bien entendu (manoeuvres luxantes).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2510, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 70 ans souffre depuis 3 mois de douleurs des épaules et des hanches et, depuis peu, d''un genou qui est le siège d''un épanchement. Les artères temporales sont bien battantes et non indurées. La V.S. est de 76/110. Il existe une anémie de type inflammatoire.', false, true, 'Quels sont les diagnostics que suggère en premier lieu cette symptomatologie ?', '[{"l":"A","t":"Une pseudo-polyarthrite rhizomélique","c":true},{"l":"B","t":"Une PR à début rhizomélique","c":true},{"l":"C","t":"Une arthrite réactionnelle","c":false},{"l":"D","t":"Un RAA","c":false},{"l":"E","t":"Une péri-artérite noueuse","c":false}]'::jsonb, 'Il s''agit en effet des principaux diagnostics à évoquer devant des douleurs inflammatoires rhizoméliques chez un sujet âgé avec un grand syndrome inflammatoire. L''arthrite du genou n''est pas suffisamment discriminative.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2511, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 70 ans souffre depuis 3 mois de douleurs des épaules et des hanches et, depuis peu, d''un genou qui est le siège d''un épanchement. Les artères temporales sont bien battantes et non indurées. La V.S. est de 76/110. Il existe une anémie de type inflammatoire.', false, true, 'Une biopsie de l''artère temporale superficielle met en évidence une artérite giganto-cellulaire. Cette artérite :', '[{"l":"A","t":"Permet d''affirmer le diagnostic de maladie de Horton","c":true},{"l":"B","t":"Permet d''exclure une polyarthrite rhumatoïde","c":false},{"l":"C","t":"Permet d''exclure une périartérite noueuse","c":false},{"l":"D","t":"Peut se rencontrer dans une arthrite réactionnelle","c":false},{"l":"E","t":"Est constante dans la pseudo-polyarthrite rhizomélique","c":false}]'::jsonb, 'Il faut apprécier l''extension des lésions et dans ce contexte la BAT positive permet d''affirmer le diagnostic de maladie de Horton. Des associations Horton et PR ou PAN ont été rapportées sans qu''il soit poss ble d''en affirmer le caractère fortuit ou non.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2512, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 70 ans souffre depuis 3 mois de douleurs des épaules et des hanches et, depuis peu, d''un genou qui est le siège d''un épanchement. Les artères temporales sont bien battantes et non indurées. La V.S. est de 76/110. Il existe une anémie de type inflammatoire.', false, true, 'On procède à la recherche de facteurs rhumatoïdes. Ces facteurs sont retrouvés dans la population générale à cet âge dans', '[{"l":"A","t":"75 % des cas","c":false},{"l":"B","t":"50 % des cas","c":false},{"l":"C","t":"25 % des cas","c":true},{"l":"D","t":"5 % des cas","c":false},{"l":"E","t":"0 % des cas","c":false}]'::jsonb, 'QCM discutable étant donné la disparité des séries étudiées et des techniques. D''après MF.KAHN, environ 10 % des femmes de plus de 65 ans ont un test au latex positif (contre 5 % à la ménopause).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2513, 9, 'Rhumatologie', 'Spondylarthrites', 'Une femme de 70 ans souffre depuis 3 mois de douleurs des épaules et des hanches et, depuis peu, d''un genou qui est le siège d''un épanchement. Les artères temporales sont bien battantes et non indurées. La V.S. est de 76/110. Il existe une anémie de type inflammatoire.', false, true, 'On recherche l''antigène HLA B27. Cet antigène est retrouvé dans la population générale dans environ :', '[{"l":"A","t":"95 % des cas","c":false},{"l":"B","t":"50 % des cas","c":false},{"l":"C","t":"25 % des cas","c":true},{"l":"D","t":"5 % des cas","c":false},{"l":"E","t":"0 % des cas","c":false}]'::jsonb, 'Environ 5 % des sujets caucasoïdes sains sont porteurs de l''antigène HLA B27 et la plupart ne développeront pas de spondylarthrite.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2514, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 70 ans souffre depuis 3 mois de douleurs des épaules et des hanches et, depuis peu, d''un genou qui est le siège d''un épanchement. Les artères temporales sont bien battantes et non indurées. La V.S. est de 76/110. Il existe une anémie de type inflammatoire.', false, true, 'On prescrit au stade initial dans ce cas, un traitement comportant :', '[{"l":"A","t":"Prednisone 5 mg/j","c":false},{"l":"B","t":"Phénylbutazone 500 mg/j","c":false},{"l":"C","t":"Colchicine 1 mg/j","c":false},{"l":"D","t":"Méthotrexate 10 mg/j","c":false},{"l":"E","t":"Prédnisone 30 mg/j","c":true}]'::jsonb, 'A cet âge et en l''absence de signe clinique de maladie de Horton (en particulier ophtalmologique) on peut se contenter d''une corticothérapie à 1/2 mg/kg/j.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2515, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X. âgé de 64 ans a des douleurs lombaires basses depuis 1 mois qui l''empêchent de se mettre debout. Des clichés osseux montrent une discrète déminéralisation. A l''examen, vous relevez une douleur à la pression de la 4ème et 3ème lombaire. Il n''y a rien d''anormal au niveau du coeur, du poumon, du foie, des aires ganglionnaires de, la rate, de la peau. Sur l''hémogramme, on retrouve : GR : 3 400 000 par mm3 Plaquettes : 210 000 par mm3 Hb : 10,4 g/100 ml GB : 4 100 par mm3 Hte : 30,9 % PN : 41 %; Eo : 2 % ; L : 500 %;Mono : VGM : 90,5 fl VS : 98 mm à la première heure CCMH : 33,7 % Protéinurie + + +; Créatinine : 116 micromol/l (50-120 ; Calcémie : 2,55 millimol/l (2,24-2,6) ; Uricémie : 589 micromol/l (150- 450). Protides totaux : 80 g/l Albumine : 39,8 g/l Alpha 1 : 1,49 g/l Alpha 2 : 4,4 g/l Bêta : 30,4 g/l Gamma : 5 g/l', false, true, 'Le diagnostic de myélome est évoqué. Pour faire le bilan d''éventuelles lésions osseuses, liées à cette maladie, vous demandez des radiographies. Pour quels os ces radios vous semblent-elles utiles ?', '[{"l":"A","t":"Crâne","c":true},{"l":"B","t":"Colonne cervicale","c":true},{"l":"C","t":"Bassin","c":true},{"l":"D","t":"Pieds","c":false},{"l":"E","t":"Mains","c":false}]'::jsonb, 'L''exploration radiologique d''une anomalie phosphocalcique comprend un crâne, des mains et un bassin. Dans le cas d''un myélome, il est habituel de demander un squelette complet, mais on peut se contenter d''un crâne, d''un rachis, d''un bassin, des fémurs et des humérus.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2516, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X. âgé de 64 ans a des douleurs lombaires basses depuis 1 mois qui l''empêchent de se mettre debout. Des clichés osseux montrent une discrète déminéralisation. A l''examen, vous relevez une douleur à la pression de la 4ème et 3ème lombaire. Il n''y a rien d''anormal au niveau du coeur, du poumon, du foie, des aires ganglionnaires de, la rate, de la peau. Sur l''hémogramme, on retrouve : GR : 3 400 000 par mm3 Plaquettes : 210 000 par mm3 Hb : 10,4 g/100 ml GB : 4 100 par mm3 Hte : 30,9 % PN : 41 %; Eo : 2 % ; L : 500 %;Mono : VGM : 90,5 fl VS : 98 mm à la première heure CCMH : 33,7 % Protéinurie + + +; Créatinine : 116 micromol/l (50-120 ; Calcémie : 2,55 millimol/l (2,24-2,6) ; Uricémie : 589 micromol/l (150- 450). Protides totaux : 80 g/l Albumine : 39,8 g/l Alpha 1 : 1,49 g/l Alpha 2 : 4,4 g/l Bêta : 30,4 g/l Gamma : 5 g/l', false, true, 'Sur ces radiographies, vous pouvez retrouver dans les cas habituels les anomalies suivantes :', '[{"l":"A","t":"Une fracture pathologique","c":true},{"l":"B","t":"Une déminéralisation diffuse","c":true},{"l":"C","t":"Des lacunes ostéolytiques multiples et arrondies","c":true},{"l":"D","t":"Un tassement vertébral","c":true},{"l":"E","t":"Des images ostéolytiques diffuses avec plages de condensation","c":false}]'::jsonb, 'En cas de forme déminéralisante, il existe des tassements en galette. Les formes habituelles sont ostéolytiques pures avec lacunes à l''emporte-pièces qui peuvent être responsables de fractures pathologiques.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2517, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X. âgé de 64 ans a des douleurs lombaires basses depuis 1 mois qui l''empêchent de se mettre debout. Des clichés osseux montrent une discrète déminéralisation. A l''examen, vous relevez une douleur à la pression de la 4ème et 3ème lombaire. Il n''y a rien d''anormal au niveau du coeur, du poumon, du foie, des aires ganglionnaires de, la rate, de la peau. Sur l''hémogramme, on retrouve : GR : 3 400 000 par mm3 Plaquettes : 210 000 par mm3 Hb : 10,4 g/100 ml GB : 4 100 par mm3 Hte : 30,9 % PN : 41 %; Eo : 2 % ; L : 500 %;Mono : VGM : 90,5 fl VS : 98 mm à la première heure CCMH : 33,7 % Protéinurie + + +; Créatinine : 116 micromol/l (50-120 ; Calcémie : 2,55 millimol/l (2,24-2,6) ; Uricémie : 589 micromol/l (150- 450). Protides totaux : 80 g/l Albumine : 39,8 g/l Alpha 1 : 1,49 g/l Alpha 2 : 4,4 g/l Bêta : 30,4 g/l Gamma : 5 g/l', false, true, 'La preuve formelle du myélome vous sera apportée le plus souvent avec certitude par un examen. Lequel ?', '[{"l":"A","t":"La bêta 2 microglobuline sérique","c":false},{"l":"B","t":"Immuno-électrophorèse (ou immuno fixation)","c":false},{"l":"C","t":"Scintigraphie osseuse","c":false},{"l":"D","t":"Myélogramme","c":true},{"l":"E","t":"Biopsie rénale","c":false}]'::jsonb, 'Il recherche une plasmocytose à plus de 30 % avec anomalies cytologiques des plasmocytes. En effet, il peut exister un pic monoclonal à l''immunoélectrophorèse au cours de la maladie de Waldenstrm ou de certains lymphomes.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2518, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X. âgé de 64 ans a des douleurs lombaires basses depuis 1 mois qui l''empêchent de se mettre debout. Des clichés osseux montrent une discrète déminéralisation. A l''examen, vous relevez une douleur à la pression de la 4ème et 3ème lombaire. Il n''y a rien d''anormal au niveau du coeur, du poumon, du foie, des aires ganglionnaires de, la rate, de la peau. Sur l''hémogramme, on retrouve : GR : 3 400 000 par mm3 Plaquettes : 210 000 par mm3 Hb : 10,4 g/100 ml GB : 4 100 par mm3 Hte : 30,9 % PN : 41 %; Eo : 2 % ; L : 500 %;Mono : VGM : 90,5 fl VS : 98 mm à la première heure CCMH : 33,7 % Protéinurie + + +; Créatinine : 116 micromol/l (50-120 ; Calcémie : 2,55 millimol/l (2,24-2,6) ; Uricémie : 589 micromol/l (150- 450). Protides totaux : 80 g/l Albumine : 39,8 g/l Alpha 1 : 1,49 g/l Alpha 2 : 4,4 g/l Bêta : 30,4 g/l Gamma : 5 g/l', false, true, 'L''existence de la protéinurie dans cette affection vous amène à demander que soit recherchée une protéinurie de Bence Jones. Quelles affirmations sont-elles vraies concernant cette anomalie ?', '[{"l":"A","t":"Protéinurie définie habituellement par la présence exclusive de chaînes lourdes d''immunoglobulines","c":false},{"l":"B","t":"Protéinurie thermo-soluble à 56°C","c":true},{"l":"C","t":"Protéinurie parfois non détectée par la méthode des bandelettes","c":true},{"l":"D","t":"Protéinurie jouant un rôle décisif dans la constitution des lésions rénales du myélome","c":true},{"l":"E","t":"Protéinurie massive dans certains myélomes","c":true}]'::jsonb, 'Il existe une resolubilisation à 100°C des chaines légères qui sont responsables d''une tabulopathie distale. Elles ne sont pas le seul facteur de déclenchement de l''IR, mais le principal.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2519, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X. âgé de 64 ans a des douleurs lombaires basses depuis 1 mois qui l''empêchent de se mettre debout. Des clichés osseux montrent une discrète déminéralisation. A l''examen, vous relevez une douleur à la pression de la 4ème et 3ème lombaire. Il n''y a rien d''anormal au niveau du coeur, du poumon, du foie, des aires ganglionnaires de, la rate, de la peau. Sur l''hémogramme, on retrouve : GR : 3 400 000 par mm3 Plaquettes : 210 000 par mm3 Hb : 10,4 g/100 ml GB : 4 100 par mm3 Hte : 30,9 % PN : 41 %; Eo : 2 % ; L : 500 %;Mono : VGM : 90,5 fl VS : 98 mm à la première heure CCMH : 33,7 % Protéinurie + + +; Créatinine : 116 micromol/l (50-120 ; Calcémie : 2,55 millimol/l (2,24-2,6) ; Uricémie : 589 micromol/l (150- 450). Protides totaux : 80 g/l Albumine : 39,8 g/l Alpha 1 : 1,49 g/l Alpha 2 : 4,4 g/l Bêta : 30,4 g/l Gamma : 5 g/l', false, true, 'Ce patient peut développer une infection bactérienne grave. Quelle en est la raison la plus probable ?', '[{"l":"A","t":"Neutropénie","c":false},{"l":"B","t":"Anomalies des fonctions des polynucléaires","c":false},{"l":"C","t":"Hypogammaglobulinémie polyclonale","c":true},{"l":"D","t":"Déficit en Iymphocytes CD4","c":false},{"l":"E","t":"Insuffisance rénale chronique","c":false}]'::jsonb, 'Le clone plasmocytaire malin est responsable de la suppression des autres clones plasmocytaires et donc d''une diminution de la synthèse des immunoglobulines normales. Il y a aussi inhibition des fonctions lymphocytaires et perturbation de l''hématémèse. Il s''agit très souvent d''une infection à pneumocoques.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2520, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X. âgé de 64 ans a des douleurs lombaires basses depuis 1 mois qui l''empêchent de se mettre debout. Des clichés osseux montrent une discrète déminéralisation. A l''examen, vous relevez une douleur à la pression de la 4ème et 3ème lombaire. Il n''y a rien d''anormal au niveau du coeur, du poumon, du foie, des aires ganglionnaires de, la rate, de la peau. Sur l''hémogramme, on retrouve : GR : 3 400 000 par mm3 Plaquettes : 210 000 par mm3 Hb : 10,4 g/100 ml GB : 4 100 par mm3 Hte : 30,9 % PN : 41 %; Eo : 2 % ; L : 500 %;Mono : VGM : 90,5 fl VS : 98 mm à la première heure CCMH : 33,7 % Protéinurie + + +; Créatinine : 116 micromol/l (50-120 ; Calcémie : 2,55 millimol/l (2,24-2,6) ; Uricémie : 589 micromol/l (150- 450). Protides totaux : 80 g/l Albumine : 39,8 g/l Alpha 1 : 1,49 g/l Alpha 2 : 4,4 g/l Bêta : 30,4 g/l Gamma : 5 g/l', false, true, 'L''anémie présentée dans ce cas par ce malade peut avoir plusieurs explications. Lesquelles ?', '[{"l":"A","t":"Insuffisance rénale","c":true},{"l":"B","t":"Insuffisance médullaire","c":true},{"l":"C","t":"Hémodilution favorisée par l''hyperprotidémie","c":true},{"l":"D","t":"Saignement chronique","c":false},{"l":"E","t":"Carence en acide folique (dénutrition)","c":true}]'::jsonb, 'Sauf thrombopénie ou syndrome d''hyperviscosité, les saignements chroniques ne sont pas habituels au cours du myélome.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2521, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X. âgé de 64 ans a des douleurs lombaires basses depuis 1 mois qui l''empêchent de se mettre debout. Des clichés osseux montrent une discrète déminéralisation. A l''examen, vous relevez une douleur à la pression de la 4ème et 3ème lombaire. Il n''y a rien d''anormal au niveau du coeur, du poumon, du foie, des aires ganglionnaires de, la rate, de la peau. Sur l''hémogramme, on retrouve : GR : 3 400 000 par mm3 Plaquettes : 210 000 par mm3 Hb : 10,4 g/100 ml GB : 4 100 par mm3 Hte : 30,9 % PN : 41 %; Eo : 2 % ; L : 500 %;Mono : VGM : 90,5 fl VS : 98 mm à la première heure CCMH : 33,7 % Protéinurie + + +; Créatinine : 116 micromol/l (50-120 ; Calcémie : 2,55 millimol/l (2,24-2,6) ; Uricémie : 589 micromol/l (150- 450). Protides totaux : 80 g/l Albumine : 39,8 g/l Alpha 1 : 1,49 g/l Alpha 2 : 4,4 g/l Bêta : 30,4 g/l Gamma : 5 g/l', false, true, 'Le traitement de la maladie fait habituellement appel à différents produits. Lesquels ?', '[{"l":"A","t":"Melphalan (Alkeran®)","c":true},{"l":"B","t":"Corticoïdes","c":true},{"l":"C","t":"Busulfan (Misulban®)","c":false},{"l":"D","t":"Cyclophosphamide (Endoxan®)","c":true},{"l":"E","t":"5 fluoro-uracile","c":false}]'::jsonb, 'En terme de survie, aucun protocole polychimiothérapique n''a fait la preuve de sa supériorité par rapport à l''association melphalan-prednisone. En terme de réponse (% de diminution du pic), l''adjonction de cyclophosphamide est intéressante mais le VBAP x VMCP n''a rien donné de bon, même si certains continuent à l''utiliser.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2522, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X. âgé de 64 ans a des douleurs lombaires basses depuis 1 mois qui l''empêchent de se mettre debout. Des clichés osseux montrent une discrète déminéralisation. A l''examen, vous relevez une douleur à la pression de la 4ème et 3ème lombaire. Il n''y a rien d''anormal au niveau du coeur, du poumon, du foie, des aires ganglionnaires de, la rate, de la peau. Sur l''hémogramme, on retrouve : GR : 3 400 000 par mm3 Plaquettes : 210 000 par mm3 Hb : 10,4 g/100 ml GB : 4 100 par mm3 Hte : 30,9 % PN : 41 %; Eo : 2 % ; L : 500 %;Mono : VGM : 90,5 fl VS : 98 mm à la première heure CCMH : 33,7 % Protéinurie + + +; Créatinine : 116 micromol/l (50-120 ; Calcémie : 2,55 millimol/l (2,24-2,6) ; Uricémie : 589 micromol/l (150- 450). Protides totaux : 80 g/l Albumine : 39,8 g/l Alpha 1 : 1,49 g/l Alpha 2 : 4,4 g/l Bêta : 30,4 g/l Gamma : 5 g/l', false, true, 'Sous l''effet de ce traitement l''amélioration se jugera sur la surveillance de certains examens appréciant la :', '[{"l":"A","t":"Diminution du nombre des leucocytes","c":false},{"l":"B","t":"Diminution du pic visible dans la zone des bêta-globulines","c":true},{"l":"C","t":"Diminution du nombre de lésions osseuses","c":false},{"l":"D","t":"Diminution de la protéinurie","c":true},{"l":"E","t":"Diminution de la plasmocytose médullaire","c":false}]'::jsonb, 'Le pic et la protéinurie (répétée) sont les deux examens les plus fiables et les moins invasifs. En cas de rémission d''apparence complète ou de rechute, il est légitime de refaire un myélogramme.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2523, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur X. âgé de 64 ans a des douleurs lombaires basses depuis 1 mois qui l''empêchent de se mettre debout. Des clichés osseux montrent une discrète déminéralisation. A l''examen, vous relevez une douleur à la pression de la 4ème et 3ème lombaire. Il n''y a rien d''anormal au niveau du coeur, du poumon, du foie, des aires ganglionnaires de, la rate, de la peau. Sur l''hémogramme, on retrouve : GR : 3 400 000 par mm3 Plaquettes : 210 000 par mm3 Hb : 10,4 g/100 ml GB : 4 100 par mm3 Hte : 30,9 % PN : 41 %; Eo : 2 % ; L : 500 %;Mono : VGM : 90,5 fl VS : 98 mm à la première heure CCMH : 33,7 % Protéinurie + + +; Créatinine : 116 micromol/l (50-120 ; Calcémie : 2,55 millimol/l (2,24-2,6) ; Uricémie : 589 micromol/l (150- 450). Protides totaux : 80 g/l Albumine : 39,8 g/l Alpha 1 : 1,49 g/l Alpha 2 : 4,4 g/l Bêta : 30,4 g/l Gamma : 5 g/l', false, true, 'Certains événements précipitent la survenue d''une insuffisance rénale. Lesquels ?', '[{"l":"A","t":"Hypercalcémie","c":true},{"l":"B","t":"Déshydratation","c":true},{"l":"C","t":"Prescription d''une ampicilline par voie IV","c":false},{"l":"D","t":"Réalisation d''une UIV","c":true},{"l":"E","t":"Prescription de bêta-bloquants","c":false}]'::jsonb, 'L''iode est effectivement responsable d''une précipitation des chaines légères dans les tubules.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2524, 21, 'Rhumatologie', 'Arthrite septique', 'Une femme de 55 ans, 78 kg pour 1,65 m, se plaint depuis trois jours d''une impotence fonctionnelle du membre inférieur droit avec température à 38,2°C, sans notion de traumatisme. Dans ses antécédents, on note un diabète traité par régime et glucophage retard®, une hystérectomie pour fibrome à l''âge de 50 ans, une hypertension artérielle modérée traitée depuis 2 ans par Moduretic® 1 cp/j, une cure chirurgicale d''un ongle incarné un mois avant l''épisode actuel. A l''examen, le genou est chaud, douloureux spontanément et à la mobilisation, il existe un choc rotulien, le mollet est souple, il n''y a pas d''oedème, le reste de l''examen est sans particularité. Biologie : leucocytes = 11 500/mm3, poly.neutro.= 78 %, VS = 105 mm à la première heure.', false, true, 'Parmi les hypothèses diagnostiques suivantes, laquelle doit être évoquée en priorité ?', '[{"l":"A","t":"Polyarthrite rhumatoïde à début monoarticulaire","c":false},{"l":"B","t":"Crise de goutte","c":false},{"l":"C","t":"Arthrite septique","c":true},{"l":"D","t":"Poussée de gonarthrose","c":false},{"l":"E","t":"Arthrite réactionnelle","c":false}]'::jsonb, 'Devant une monoarthrite, il faut toujours éliminer une arthrite septique, d''autant qu''elle est fébrile. Il peut s''agir d''une arthrite microcristalline mais une polyarthrite rhumatoïde ne donne pas de VS à 105 mm sauf complication intercurrente (surinfection, vascularite...).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2525, 21, 'Rhumatologie', 'Arthrite septique', 'Une femme de 55 ans, 78 kg pour 1,65 m, se plaint depuis trois jours d''une impotence fonctionnelle du membre inférieur droit avec température à 38,2°C, sans notion de traumatisme. Dans ses antécédents, on note un diabète traité par régime et glucophage retard®, une hystérectomie pour fibrome à l''âge de 50 ans, une hypertension artérielle modérée traitée depuis 2 ans par Moduretic® 1 cp/j, une cure chirurgicale d''un ongle incarné un mois avant l''épisode actuel. A l''examen, le genou est chaud, douloureux spontanément et à la mobilisation, il existe un choc rotulien, le mollet est souple, il n''y a pas d''oedème, le reste de l''examen est sans particularité. Biologie : leucocytes = 11 500/mm3, poly.neutro.= 78 %, VS = 105 mm à la première heure.', false, true, 'Quel examen vous permet de confirmer votre hypothèse ?', '[{"l":"A","t":"Test au latex-réaction de Waaler-Rose","c":false},{"l":"B","t":"Ponction articulaire","c":true},{"l":"C","t":"Dosages de l''uricémie et de l''uraturie","c":false},{"l":"D","t":"Arthroscopie","c":false},{"l":"E","t":"Groupage HLA","c":false}]'::jsonb, 'Il s''agit du premier geste à faire avec examen cytobactériologique du liquide articulaire (direct + culture) et recherche de microcristaux.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2526, 21, 'Rhumatologie', 'Arthrite septique', 'Une femme de 55 ans, 78 kg pour 1,65 m, se plaint depuis trois jours d''une impotence fonctionnelle du membre inférieur droit avec température à 38,2°C, sans notion de traumatisme. Dans ses antécédents, on note un diabète traité par régime et glucophage retard®, une hystérectomie pour fibrome à l''âge de 50 ans, une hypertension artérielle modérée traitée depuis 2 ans par Moduretic® 1 cp/j, une cure chirurgicale d''un ongle incarné un mois avant l''épisode actuel. A l''examen, le genou est chaud, douloureux spontanément et à la mobilisation, il existe un choc rotulien, le mollet est souple, il n''y a pas d''oedème, le reste de l''examen est sans particularité. Biologie : leucocytes = 11 500/mm3, poly.neutro.= 78 %, VS = 105 mm à la première heure.', false, true, 'Quelle(s) exploration(s) complémentaire(s) devez-vous proposer ?', '[{"l":"A","t":"Radiographies du genou","c":true},{"l":"B","t":"Scintigraphie osseuse","c":false},{"l":"C","t":"Hémocultures","c":true},{"l":"D","t":"Séro-diagnostic des chlamydiae","c":false},{"l":"E","t":"Etude de l''immunité cellulaire","c":false}]'::jsonb, 'Plutôt qu''une radiographie du genou, je demanderais plutôt une radiographie comparative des genoux.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2527, 21, 'Rhumatologie', 'Arthrite septique', 'Une femme de 55 ans, 78 kg pour 1,65 m, se plaint depuis trois jours d''une impotence fonctionnelle du membre inférieur droit avec température à 38,2°C, sans notion de traumatisme. Dans ses antécédents, on note un diabète traité par régime et glucophage retard®, une hystérectomie pour fibrome à l''âge de 50 ans, une hypertension artérielle modérée traitée depuis 2 ans par Moduretic® 1 cp/j, une cure chirurgicale d''un ongle incarné un mois avant l''épisode actuel. A l''examen, le genou est chaud, douloureux spontanément et à la mobilisation, il existe un choc rotulien, le mollet est souple, il n''y a pas d''oedème, le reste de l''examen est sans particularité. Biologie : leucocytes = 11 500/mm3, poly.neutro.= 78 %, VS = 105 mm à la première heure.', false, true, 'Le traitement doit comporter, outre l''antibiothérapie générale :', '[{"l":"A","t":"Ponction et lavage de l''articulation","c":true},{"l":"B","t":"Antibiothérapie intra-articulaire","c":false},{"l":"C","t":"Immobilisation","c":true},{"l":"D","t":"Rééducation statique du quadriceps","c":true},{"l":"E","t":"Corticothérapie par voie générale","c":false}]'::jsonb, 'Antibiothérapie et immobilisation sont les deux mamelles du traitement d''une arthrite septique. La rééducation statique du quadriceps est indiquée en raison de la rapide amyotrophie de celui-ci. B et E sont des fautes thérapeutiques. Il peut être utile d''équilibrer le diabète...', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2528, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Une femme de 66 ans souffre depuis une semaine d''une douleur du genou gauche d''apparition brutale et d''horaire nocturne. Il n''y a pas d''antécédents articulaires. La malade est traitée par le Furosemide (Lasilix®) 40 mg/jour pour hypertension artérielle. A l''examen le genou est gonflé, chaud, douloureux au palper et limité dans la flexion. Le reste de l''examen articulaire est normal. La tension artérielle est à 16-9 cm Hg. Il n''y a pas de signe d''atteinte viscérale. Le poids est de 50 kg pour 1,60 m et l''alimentation est équilibrée. La VS est à 100 mm à la l ère heure. Le taux d''hémoglobine à 9 g/100 ml, l''uricémie à 90 mg/l (540 micromol/l) la créatininémie à 140 micromol/l, la calcémie à 120 mg/l (3 mmol/l), la phosphorémie à 31 mg/l (1 mmol/l), la sidérémie est normale ainsi que la férritinémie. La radiographie des genoux montre des calcifications des ménisques et un genu varum.', false, true, 'Quels sont les arguments pour la goutte ?', '[{"l":"A","t":"Sensibilité à la colchicine","c":true},{"l":"B","t":"Traitement par le furosémide","c":false},{"l":"C","t":"Absence de tophus","c":false},{"l":"D","t":"Uricémie à 90 mg/l","c":true},{"l":"E","t":"Présence de cristaux d''urate de sodium dans le liquide synovial","c":true}]'::jsonb, 'QCM discutable dans sa formulation. En général, les critères A et D sont évocateurs et l''examen du liquide articulaire fera le diagnostic. Mais le tableau présenté est peu évocateur malgré l''hyperuricémie secondaire à l''insuffisance rénale et à la prise de furosémide.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2529, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Une femme de 66 ans souffre depuis une semaine d''une douleur du genou gauche d''apparition brutale et d''horaire nocturne. Il n''y a pas d''antécédents articulaires. La malade est traitée par le Furosemide (Lasilix®) 40 mg/jour pour hypertension artérielle. A l''examen le genou est gonflé, chaud, douloureux au palper et limité dans la flexion. Le reste de l''examen articulaire est normal. La tension artérielle est à 16-9 cm Hg. Il n''y a pas de signe d''atteinte viscérale. Le poids est de 50 kg pour 1,60 m et l''alimentation est équilibrée. La VS est à 100 mm à la l ère heure. Le taux d''hémoglobine à 9 g/100 ml, l''uricémie à 90 mg/l (540 micromol/l) la créatininémie à 140 micromol/l, la calcémie à 120 mg/l (3 mmol/l), la phosphorémie à 31 mg/l (1 mmol/l), la sidérémie est normale ainsi que la férritinémie. La radiographie des genoux montre des calcifications des ménisques et un genu varum.', false, true, 'Quels sont les arguments pour la chondrocalcinose ?', '[{"l":"A","t":"Liquide synovial mécanique","c":false},{"l":"B","t":"Il s''agit d''un sujet âgé","c":true},{"l":"C","t":"Présence de calcifications méniscales","c":true},{"l":"D","t":"Présence d''un genu varum","c":false},{"l":"E","t":"Présence de microcristaux de pyrophosphate de calcium dans le liquide synovial","c":true}]'::jsonb, 'Le liquide est souvent puriforme. Les calcifications des fibrocartilages se retrouvent sur les poignets et la symphyse pubienne, ainsi qu''aux épaules, genoux...', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2530, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Une femme de 66 ans souffre depuis une semaine d''une douleur du genou gauche d''apparition brutale et d''horaire nocturne. Il n''y a pas d''antécédents articulaires. La malade est traitée par le Furosemide (Lasilix®) 40 mg/jour pour hypertension artérielle. A l''examen le genou est gonflé, chaud, douloureux au palper et limité dans la flexion. Le reste de l''examen articulaire est normal. La tension artérielle est à 16-9 cm Hg. Il n''y a pas de signe d''atteinte viscérale. Le poids est de 50 kg pour 1,60 m et l''alimentation est équilibrée. La VS est à 100 mm à la l ère heure. Le taux d''hémoglobine à 9 g/100 ml, l''uricémie à 90 mg/l (540 micromol/l) la créatininémie à 140 micromol/l, la calcémie à 120 mg/l (3 mmol/l), la phosphorémie à 31 mg/l (1 mmol/l), la sidérémie est normale ainsi que la férritinémie. La radiographie des genoux montre des calcifications des ménisques et un genu varum.', false, true, 'Quelles sont les causes ou facteurs prédisposants possibles de la chondrocalcinose de cette malade ?', '[{"l":"A","t":"L''âge","c":true},{"l":"B","t":"Insuffisance rénale chronique","c":false},{"l":"C","t":"Hyperparathyroïdisme primitif","c":true},{"l":"D","t":"Hypercalcémie paranéoplasique","c":false},{"l":"E","t":"Hémochromatose","c":false}]'::jsonb, 'Il n''y a pas de signe d''hémochromatose, ni d''hypomagnésémie, ni d''hypophosphatasémie. Par contre, il existe une hypercalcémie nette et bien tolérée, donc chronique. La phosphorémie normale et inadaptée dans ce contexte s''explique par l''insuffisance rénale.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2531, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Une femme de 66 ans souffre depuis une semaine d''une douleur du genou gauche d''apparition brutale et d''horaire nocturne. Il n''y a pas d''antécédents articulaires. La malade est traitée par le Furosemide (Lasilix®) 40 mg/jour pour hypertension artérielle. A l''examen le genou est gonflé, chaud, douloureux au palper et limité dans la flexion. Le reste de l''examen articulaire est normal. La tension artérielle est à 16-9 cm Hg. Il n''y a pas de signe d''atteinte viscérale. Le poids est de 50 kg pour 1,60 m et l''alimentation est équilibrée. La VS est à 100 mm à la l ère heure. Le taux d''hémoglobine à 9 g/100 ml, l''uricémie à 90 mg/l (540 micromol/l) la créatininémie à 140 micromol/l, la calcémie à 120 mg/l (3 mmol/l), la phosphorémie à 31 mg/l (1 mmol/l), la sidérémie est normale ainsi que la férritinémie. La radiographie des genoux montre des calcifications des ménisques et un genu varum.', false, true, 'Quels sont les arguments pour un adénome parathyroïdien à l''origine de la chondrocalcinose ?', '[{"l":"A","t":"Hypercalcémie","c":true},{"l":"B","t":"Phosphorémie normale","c":false},{"l":"C","t":"Lithiase urinaire","c":true},{"l":"D","t":"Sidérémie normale","c":false},{"l":"E","t":"Echographie cervicale normale","c":false}]'::jsonb, 'La phosphorémie est normale en raison de l''IRC. Une échographie normale n''élimine pas le diagnostic d''adénome parathyroïdien qui est souvent petit et parfois ectopique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2532, 9, 'Rhumatologie', 'Spondylarthrites', 'Un jeune homme de 25 ans souffre d''une oligoarthrite touchant les genoux et les chevilles, apparue une semaine après une urétrite d''origine vénérienne. Son médecin lui prescrit un traitement par pénicilline G (10 millions d''U. par jour pendant 10 jours) sans aucune efficacité. On évoque le diagnostic de syndrome de Fiessinger-Leroy-Reiter.', false, true, 'Dans l''affection en cause, on trouve l''antigène HLA B27 dans environ :', '[{"l":"A","t":"98 % des cas","c":false},{"l":"B","t":"75 % des cas","c":true},{"l":"C","t":"40 % des cas","c":false},{"l":"D","t":"25 % des cas","c":false},{"l":"E","t":"5 % des cas","c":false}]'::jsonb, 'Connaissance.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2533, 9, 'Rhumatologie', 'Spondylarthrites', 'Un jeune homme de 25 ans souffre d''une oligoarthrite touchant les genoux et les chevilles, apparue une semaine après une urétrite d''origine vénérienne. Son médecin lui prescrit un traitement par pénicilline G (10 millions d''U. par jour pendant 10 jours) sans aucune efficacité. On évoque le diagnostic de syndrome de Fiessinger-Leroy-Reiter.', false, true, 'A l''origine de l''urétrite, on soupçonne une infection à chlamydia trachomatis. Pour confirmer cette étiologie, on procède à :', '[{"l":"A","t":"Une culture de prélèvements urétraux","c":false},{"l":"B","t":"Une recherche d''anticorps anti-chlamydiae","c":true},{"l":"C","t":"Un examen en immunofluorescence du prélèvement urétral","c":true},{"l":"D","t":"Une hémoculture","c":false},{"l":"E","t":"Une culture du liquide articulaire","c":false}]'::jsonb, 'Que de pièges ! Le liquide articulaire est aseptique car il s''agit d''une arthrite "réactionnelle" à un foyer infectieux à distance et le plus souvent guéri.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2534, 9, 'Rhumatologie', 'Spondylarthrites', 'Un jeune homme de 25 ans souffre d''une oligoarthrite touchant les genoux et les chevilles, apparue une semaine après une urétrite d''origine vénérienne. Son médecin lui prescrit un traitement par pénicilline G (10 millions d''U. par jour pendant 10 jours) sans aucune efficacité. On évoque le diagnostic de syndrome de Fiessinger-Leroy-Reiter.', false, true, 'En raison de sa maladie, le sujet risque plusieurs des complications suivantes. Lesquelles ?', '[{"l":"A","t":"Arthropathie destructrice","c":false},{"l":"B","t":"Séquelles d''uvéite","c":true},{"l":"C","t":"Kératodermie palmo-plantaire","c":true},{"l":"D","t":"Calcanéïte","c":true},{"l":"E","t":"Spondylarthrite ankylosante","c":true}]'::jsonb, 'L''uvéite est beaucoup moins fréquente que la conjonctivite dans cette affection mais elle est néanmoins possible ; à la différence d''une arthropathie destructrice, le pronostic fonctionnel est dominé par les rechutes douloureuses et invalidantes.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2535, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Un jeune homme de 25 ans souffre d''une oligoarthrite touchant les genoux et les chevilles, apparue une semaine après une urétrite d''origine vénérienne. Son médecin lui prescrit un traitement par pénicilline G (10 millions d''U. par jour pendant 10 jours) sans aucune efficacité. On évoque le diagnostic de syndrome de Fiessinger-Leroy-Reiter.', false, true, 'Le traitement des arthrites réactionnelles fait appel en première intention :', '[{"l":"A","t":"Aux immunosuppresseurs","c":false},{"l":"B","t":"Aux anti-inflammatoires non stéroïdiens","c":true},{"l":"C","t":"Aux céphalosporines","c":false},{"l":"D","t":"A la colchicine","c":false},{"l":"E","t":"Aux corticoïdes","c":false}]'::jsonb, 'C''est même le seul traitement le plus souvent utilisé. Des corticoïdes locaux peuvent être utilisées en infiltration d''une arthrite ou d''une entésopathie rebelle.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2536, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 68 ans a dans ses antécédents lointains un ulcère bu baire. Elle se plaint depuis 2 mois de douleurs inflammatoires des ceintures scapulaire et pelvienne avec impotence fonctionnelle majeure. Il existe une asthénie, un amaigrissement de 4 kg; depuis une semaine des céphalées bitemporales sont apparues. La mobilisation passive des articulations est peu douloureuse : il existe une tuméfaction inflammatoire des 2 artères temporales dont les pouls ne sont pas perçus. Elle pèse 60 kg, les radiographies sont normales. vitesse de sédimentation : 90 mm à la première heure. NFS : anémie inflammatoire modérée.', false, true, 'Quel est le diagnostic le plus probable ?', '[{"l":"A","t":"Polyarthrite rhumatoïde","c":false},{"l":"B","t":"Polymyosite","c":false},{"l":"C","t":"Pseudo-polyarthrite rhizomélique","c":false},{"l":"D","t":"Maladie de Horton","c":true},{"l":"E","t":"Métastases osseuses","c":false}]'::jsonb, 'Sur la foi des signes temporaux. En cas de QCM à réponse multiple, il aurait fallu répondre C et D, car la nosologie n''est pas parfaitement tranchée.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2537, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 68 ans a dans ses antécédents lointains un ulcère bu baire. Elle se plaint depuis 2 mois de douleurs inflammatoires des ceintures scapulaire et pelvienne avec impotence fonctionnelle majeure. Il existe une asthénie, un amaigrissement de 4 kg; depuis une semaine des céphalées bitemporales sont apparues. La mobilisation passive des articulations est peu douloureuse : il existe une tuméfaction inflammatoire des 2 artères temporales dont les pouls ne sont pas perçus. Elle pèse 60 kg, les radiographies sont normales. vitesse de sédimentation : 90 mm à la première heure. NFS : anémie inflammatoire modérée.', false, true, 'Quel examen allez-vous demander pour le confirmer ?', '[{"l":"A","t":"Sérologie rhumatoïde","c":false},{"l":"B","t":"Electromyogramme","c":false},{"l":"C","t":"Scintigraphie osseuse","c":false},{"l":"D","t":"Biopsie d''artère temporale","c":true},{"l":"E","t":"Enzymes musculaires","c":false}]'::jsonb, 'A la recherche d''une artérite à cellules géantes.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2538, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 68 ans a dans ses antécédents lointains un ulcère bu baire. Elle se plaint depuis 2 mois de douleurs inflammatoires des ceintures scapulaire et pelvienne avec impotence fonctionnelle majeure. Il existe une asthénie, un amaigrissement de 4 kg; depuis une semaine des céphalées bitemporales sont apparues. La mobilisation passive des articulations est peu douloureuse : il existe une tuméfaction inflammatoire des 2 artères temporales dont les pouls ne sont pas perçus. Elle pèse 60 kg, les radiographies sont normales. vitesse de sédimentation : 90 mm à la première heure. NFS : anémie inflammatoire modérée.', false, true, 'Quel traitement allez-vous instituer ?', '[{"l":"A","t":"Diclofenac 150 mg/jour","c":false},{"l":"B","t":"Dapsone 100 mg/jour","c":false},{"l":"C","t":"Prednisone 60 mg/jour","c":true},{"l":"D","t":"D-Pénicillamine 300 mg/jour","c":false},{"l":"E","t":"Méthotrexate 10 mg/semaine","c":false}]'::jsonb, 'En raison du caractère inflammatoire clinique des artères temporales faisant craindre une occlusion de l''artère centrale de la rétine, la corticothérapie sera débutée sans délai à la dose de 1 mg/kg/j.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2539, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 68 ans a dans ses antécédents lointains un ulcère bu baire. Elle se plaint depuis 2 mois de douleurs inflammatoires des ceintures scapulaire et pelvienne avec impotence fonctionnelle majeure. Il existe une asthénie, un amaigrissement de 4 kg; depuis une semaine des céphalées bitemporales sont apparues. La mobilisation passive des articulations est peu douloureuse : il existe une tuméfaction inflammatoire des 2 artères temporales dont les pouls ne sont pas perçus. Elle pèse 60 kg, les radiographies sont normales. vitesse de sédimentation : 90 mm à la première heure. NFS : anémie inflammatoire modérée.', false, true, 'Comment allez-vous apprécier l''efficacité du traitement ?', '[{"l":"A","t":"Symptomatologie douloureuse","c":true},{"l":"B","t":"Electromyogramme","c":false},{"l":"C","t":"Biopsie d''artère temporale de contrôle","c":false},{"l":"D","t":"Vitesse de sédimentation","c":true},{"l":"E","t":"Sérologie rhumatoïde","c":false}]'::jsonb, 'Au cours de l''évolution, la VS devient souvent moins fiable et c''est la clinique qui prime souvent.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2540, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 68 ans a dans ses antécédents lointains un ulcère bu baire. Elle se plaint depuis 2 mois de douleurs inflammatoires des ceintures scapulaire et pelvienne avec impotence fonctionnelle majeure. Il existe une asthénie, un amaigrissement de 4 kg; depuis une semaine des céphalées bitemporales sont apparues. La mobilisation passive des articulations est peu douloureuse : il existe une tuméfaction inflammatoire des 2 artères temporales dont les pouls ne sont pas perçus. Elle pèse 60 kg, les radiographies sont normales. vitesse de sédimentation : 90 mm à la première heure. NFS : anémie inflammatoire modérée.', false, true, 'Quelle sera la durée moyenne du traitement ?', '[{"l":"A","t":"15 jours","c":false},{"l":"B","t":"6 mois","c":false},{"l":"C","t":"18 mois","c":true},{"l":"D","t":"Jusqu''à normalisation de la vitesse de sédimentation","c":false},{"l":"E","t":"A vie","c":false}]'::jsonb, 'Il s''agit d''un traitement prolongé et la durée moyenne du traitement avoisine les 2 ans. La normalisation de la VS est recherchée mais elle n''est pas toujours obtenue.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2541, 15, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Quelles lésions redoutez-vous ?', '[{"l":"A","t":"Lésion du fléchisseur profond du majeur","c":false},{"l":"B","t":"Lésion du fléchisseur superficiel du majeur","c":true},{"l":"C","t":"Lésion du nerf ulnaire","c":false},{"l":"D","t":"Lésion du nerf médian","c":true},{"l":"E","t":"Lésion du nerf digital commun du III","c":false}]'::jsonb, 'Conseil du spécialiste : Des questions très axées anatomie I clinique, mais avec les QCM ça pourrait sélectionner de nombreux candidats, en plus c''est utile en pratique quotidienne.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2542, 15, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Quelles anomalies auriez-vous attendu en cas de lésion unique du nerf radial au niveau de ses branches motrices et sensitives ?', '[{"l":"A","t":"Disparition de l''effet ténodèse en extension du poignet","c":false},{"l":"B","t":"Anesthésie de la face dorsale (externe) du pouce","c":true},{"l":"C","t":"Anesthésie de la face dorsale de la deuxième phalange de l''index","c":false},{"l":"D","t":"Déficit de l''opposition du pouce","c":false},{"l":"E","t":"Déficit de l''abduction du pouce","c":true}]'::jsonb, 'Conseil du spécialiste : Des questions très axées anatomie I clinique, mais avec les QCM ça pourrait sélectionner de nombreux candidats, en plus c''est utile en pratique quotidienne.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2543, 15, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Quels examens complémentaires prescrivez-vous ?', '[{"l":"A","t":"Radiographie de la main et du poignet droit pour rechercher des corps étranger du type morceaux de verre.","c":true},{"l":"B","t":"Hémocultures","c":false},{"l":"C","t":"Test rapide de mise en évidence de l''immuno-protection antitétanique","c":true},{"l":"D","t":"HCG","c":false},{"l":"E","t":"Bilan pré-opératoire avec radiographie thoracique et bilan d''hémostase","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2544, 15, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Quelle sera la prise en charge de ce malade au SAU ?', '[{"l":"A","t":"Antibiothérapie sans attendre le transfert du malade en orthopédie","c":false},{"l":"B","t":"Retrait du corps étranger sous MEOPA.","c":false},{"l":"C","t":"Suture par points séparés","c":false},{"l":"D","t":"Désinfection par un antiseptique.","c":true},{"l":"E","t":"Pose d''un garrot pneumatique","c":false}]'::jsonb, 'Conseil du spécialiste : Attention : plaie de main = exploration chirurgicale en urgence +++ pas de suture, cicatrisation dirigée.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2545, 15, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Quelle sera la prise en charge par le chirurgien orthopédique?', '[{"l":"A","t":"Exploration au bloc opératoire à distance","c":false},{"l":"B","t":"Prélèvements bactériologiques","c":true},{"l":"C","t":"Suture des nerfs sectionnés","c":true},{"l":"D","t":"Suture des tendons sectionnés","c":true},{"l":"E","t":"Cicatrisation dirigée","c":true}]'::jsonb, 'Conseil du spécialiste : Attention : plaie de main = exploration chirurgicale en urgence +++ pas de suture, cicatrisation dirigée.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2546, 15, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Vous apprenez que le patient est allergique à l''amoxicilline pour laquelle il a présenté un œdème de Quincke. Quelle antibiothérapie privilégiez-vous ?', '[{"l":"A","t":"Augmentin","c":false},{"l":"B","t":"Clindamycine","c":true},{"l":"C","t":"Métronidazol","c":false},{"l":"D","t":"Cefprodoxine-proxétile","c":false},{"l":"E","t":"Aucune antibiothérapie n''est nécessaire si la plaie du patient n''est pas souillée","c":false}]'::jsonb, 'Conseil du spécialiste : ATB obligatoire car exposition tendineuse et nerveuse.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2547, 15, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Le patient n''est pas vacciné contre le tétanos, quelle est votre conduite à tenir ?', '[{"l":"A","t":"Injection de sérum antitétanique et d''une dose de vaccin dans le bras touché.","c":false},{"l":"B","t":"Injection de sérum antitétanique et d''une dose de vaccin dans le bras sain.","c":false},{"l":"C","t":"Injection de sérum antitétanique seul.","c":false},{"l":"D","t":"Injection d''une dose de vaccin antitétanique seule.","c":false},{"l":"E","t":"Aucune de ces réponses","c":true}]'::jsonb, 'Conseil du spécialiste : Corps étranger = plaie grave = sérum + vaccin dans un bras différent à JO, deuxième dose de vaccin à J30 et rappel à 1 an.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2548, 15, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Quelles sont vos recommandations concernant la suite de la prise en charge du risque tétanique ?', '[{"l":"A","t":"Deuxième injection de sérum antitétanique à 30 jours","c":false},{"l":"B","t":"Deuxième dose de vaccin antitétanique à 30 jours","c":true},{"l":"C","t":"Rappel vaccinal à 1 an","c":true},{"l":"D","t":"Rappel vaccinal à 5 ans","c":false},{"l":"E","t":"Aucune de ces réponses","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2549, 15, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Finalement, c''est peu surpris que vous apprenez que le patient est sorti contre avis médical. Il revient deux jours plus tard aux urgences. Vous pensez immédiatement à un phlégmon de la gaine du fléchisseur du majeur droit collecté. Quels sont les arguments cliniques en faveur?', '[{"l":"A","t":"Adénopathies axillaires droites","c":true},{"l":"B","t":"Douleur à la palpation du cul-de-sac proximal de la gaine, en regard de l''articulation tarso-métatarsienne","c":false},{"l":"C","t":"Adénopathies épitrochléennes droites","c":true},{"l":"D","t":"Douleur majorée à la flexion du doigt","c":false},{"l":"E","t":"Douleur pulsatile insomniante","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2550, 15, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Quel germe est le plus souvent responsable de cette affection?', '[{"l":"A","t":"Staphylococcus aureus","c":true},{"l":"B","t":"Streptocoque A","c":false},{"l":"C","t":"E. coli","c":false},{"l":"D","t":"Pseudomonas aeruginosa","c":false},{"l":"E","t":"Klebsielle","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2551, 43, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Quels éléments vous orienteraient vers une ténosynovite nécrosante ?', '[{"l":"A","t":"Syndrome de Volkmann","c":false},{"l":"B","t":"Crochet irréductible du doigt","c":false},{"l":"C","t":"Crépitation neigeuse sous-cutanée","c":false},{"l":"D","t":"Absence de crochet du doigt","c":true},{"l":"E","t":"Peau cartonnée en regard de la gaine","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2552, 15, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Quelles sont les étapes du traitement chirurgical ?', '[{"l":"A","t":"Mise à plat de la gaine concernée","c":true},{"l":"B","t":"Parage des tissus non nécrotiques","c":false},{"l":"C","t":"Lavage au sérum physiologique","c":true},{"l":"D","t":"Immobilisation en position de fonction","c":true},{"l":"E","t":"Immobilisation transitoire par fixateur externe","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2553, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'L''opération s''est bien déroulée, le patient vous demande quelle est l''évolution la plus probable de ce phlegmon collecté de la gaine du fléchisseur du majeur ?', '[{"l":"A","t":"Arthrose secondaire","c":false},{"l":"B","t":"Neuralgodystrophie","c":false},{"l":"C","t":"Ostéite","c":false},{"l":"D","t":"Raideur séquellaire","c":true},{"l":"E","t":"Aucune de ces réponses","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2554, 15, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Cette fois-ci le patient respecte vos recommandations, l''infection guérit, mais il reste une séquelle sensitive post-traumatique. Le patient souhaite porter plainte contre le chirurgien de l''hôpital qu''il tient pour responsable de cette insensibilité de la main.', '[{"l":"A","t":"La responsabilité médicale administrative de l''hôpital peut être engagée","c":true},{"l":"B","t":"La responsabilité ordinale du chirurgien peut-être engagée","c":true},{"l":"C","t":"La responsabilité pénale du chirurgien peut être engagée en cas de défaut d''information.","c":false},{"l":"D","t":"La responsabilité civile de la panseuse peut être engagée","c":true},{"l":"E","t":"La preuve de la faute est toujours à la charge du patient","c":false}]'::jsonb, 'Conseil du spécialiste : En cas de litige au pénal, c''est l''état qui est chargé de recueillir les preuves de la faute du médecin, pas le patient. Pas de pénal en cas d''absence d''information..', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2555, 15, 'Traumatologie', 'Main', 'Interne aux urgences, vous recevez un jeune de 20 ans consultant suite à une agression avec des tessons de bouteille. Il présente plusieurs plaies profondes sur le bras, le poignet et la main droite. Celles-ci vous semblent non souillées, mais vous remarquez un morceau de verre au fond d''une des plaies. Aprés un examen clinique soigné, vous retrouvez un déficit moteur en flexion de la deuxième phalange du majeur droit quand les premières phalanges de tous les doigts sont bloquées. Vous retrouvez un déficit dans la pince pouce-index et une anesthésie de l''éminence Thénar. Les pouls sont conservés mais la plaie saigne abondamment.', false, true, 'Dans le cas d''un aléa thérapeutique :', '[{"l":"A","t":"L''indemnisation est gérée par l''ONIAM","c":true},{"l":"B","t":"Le délai de prescription est de 3 ans","c":false},{"l":"C","t":"Le patient peut saisir le CRCI","c":true},{"l":"D","t":"Ce principe exclu les infections nosocomiales","c":false},{"l":"E","t":"Ne concerne que des événements ayant pour conséquence un taux d''IPP > 24 %","c":false}]'::jsonb, 'Conseil du spécialiste : Indemnisation de l''aléa thérapeutique, sous réserve d''une ITI de plus de 6 mois, d''une IPP de plus de 24 %, d''une inaptitude définitive à exercer son activité professionnelle ou de troubles particulièrement graves dans les conditions d''existence.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2556, 20, 'Rhumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Quels arguments sont en faveur d''une épitrochléite ?', '[{"l":"A","t":"Irradiation ascendante","c":false},{"l":"B","t":"Douleur à la palpation de la face interne du coude","c":true},{"l":"C","t":"Douleur majorée à l''extension","c":false},{"l":"D","t":"Douleur majorée à la pronation.","c":true},{"l":"E","t":"Diminution de la force de serrage","c":true}]'::jsonb, 'Conseil du spécialiste : L''epitrochléite (ou épicondylite médiale), c''est l''inverse du « tennis elbow ». Douleur en flexion, pronation (pensez au swing du golfeur).', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2557, 20, 'Rhumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Quel traitement antalgique lui prescrivez-vous si sa douleur est à 50/100 selon l''EVA?', '[{"l":"A","t":"Paracétamol 1 g x 41jour","c":false},{"l":"B","t":"AINS à dose minimale efficace","c":false},{"l":"C","t":"Tramadol 50 mg x 41jour","c":true},{"l":"D","t":"Association Tramadol + paracétamol en cas d''échec d''un pallier 2","c":true},{"l":"E","t":"Antalgique de palier Il (Nefopam) à dose minimale efficace","c":false}]'::jsonb, 'Conseil du spécialiste : Connaître les posologies de quelques antalgiques n''est pas du luxe. AT- TENTION le néfopam est Cl en cas d''HBP (effet anticholinergique). Les AINS Cl en cas d''UGD (plus classique).', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2558, 32, 'Rhumatologie', 'Fracture de l’humérus', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Votre traitement a été un succès, mais Monsieur D. revient vous voir cette fois pour une douleur de l''épaule droite. Votre examen clinique retrouve une douleur localisée en sous-acromial externe, déclenchée par la manœuvre de Jobe et celle de Neer. Les mobilités actives et passives sont conservées. Quelle pathologie suspectez-vous ?', '[{"l":"A","t":"Tendinite du biceps brachial","c":false},{"l":"B","t":"Rupture partielle du supra-épineux","c":false},{"l":"C","t":"Tendinite de l''infra-épineux","c":false},{"l":"D","t":"Tendinite du supra-épineux","c":true},{"l":"E","t":"Épaule douloureuse simple","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2559, 20, 'Rhumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Quels éléments caractérisent le test de Jobe ?', '[{"l":"A","t":"Abduction contrariée","c":true},{"l":"B","t":"Rotation externe contrariée","c":false},{"l":"C","t":"Bras en anté-pulsion de 30°","c":true},{"l":"D","t":"Bras dans le plan de l''omoplate","c":true},{"l":"E","t":"Pouces vers le haut","c":false}]'::jsonb, 'Conseil du spécialiste : Bien connaître les manœuvres de l''épaule.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2560, 32, 'Rhumatologie', 'Fracture de l’humérus', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Quels éléments caractérisent la manœuvre de Neer ?', '[{"l":"A","t":"Signe un conflit sous-acromial","c":true},{"l":"B","t":"Signe un conflit sous-coracoïdien","c":false},{"l":"C","t":"Manœuvre en élévation rotation externe","c":false},{"l":"D","t":"Manœuvre en rotation interne coude ftéchi à 90°","c":false},{"l":"E","t":"Nécessite l''aide du médecin","c":true}]'::jsonb, 'Conseil du spécialiste : Bien connaître les manœuvres de l''épaule.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2561, 21, 'Rhumatologie', 'Arthrite septique', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Vous le traitez encore une fois avec succès mais cette foisci c''est aux urgences que Monsieur D. consulte. li présente une douleur intense d''apparition brutale de l''épaule droite, celle-ci est chaude. Le patient vous apprend qu''il a eu une infiltration de corticoïdes chez un confrère rhumatologue il y a quelques jours. La température est à 38,4°C, il existe une impotence fonctionnelle totale. L''examen de l''épaule est impossible en raison des douleurs. Quelle est votre première hypothèse diagnostique ?', '[{"l":"A","t":"Tendinite","c":false},{"l":"B","t":"Algodystrophie","c":false},{"l":"C","t":"Épaule aiguë hyperalgique","c":false},{"l":"D","t":"Arthrite septique","c":true},{"l":"E","t":"Capsulite rétractile","c":false}]'::jsonb, 'Conseil du spécialiste : douleur + fièvre + infitration récente = arthrite septique jusqu''à preuve du contraire.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2562, 21, 'Rhumatologie', 'Arthrite septique', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Lesquelles de ces réponses élimineraient votre diagnostic ?', '[{"l":"A","t":"Protides à 55 g/1dans la ponction articulaire","c":false},{"l":"B","t":"Radiographie de l''épaule normale","c":false},{"l":"C","t":"Absence de germe à l''examen direct bactériologique de la ponction articulaire","c":false},{"l":"D","t":"Cellularité à 900 / mm 3 à la ponction articulaire","c":true},{"l":"E","t":"Aucune de ces réponses","c":false}]'::jsonb, 'Conseil du spécialiste : Épanchement inflammatoire = liquide citrin ou purulent, cellularité > 2000 I mm'', PNN > 50 %, protéines> 40 g/I', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2563, 21, 'Rhumatologie', 'Arthrite septique', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Cette hypothèse est réfutée. Quel est alors le diagnostic le plus probable ?', '[{"l":"A","t":"Tendinite de sus-épineux","c":false},{"l":"B","t":"Algodystrophie","c":false},{"l":"C","t":"Épaule aiguë hyperalgique","c":true},{"l":"D","t":"Arthrite septique","c":false},{"l":"E","t":"Capsulite rétractile","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2564, 20, 'Rhumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Quels traitements auraient eu un effet antalgique ?', '[{"l":"A","t":"Ponction évacuatrice de la bourse sous acromiale","c":true},{"l":"B","t":"Ponction-aspiration de l''articulation orna-humérale","c":false},{"l":"C","t":"Infiltration de corticoïdes","c":true},{"l":"D","t":"Immobilisation","c":true},{"l":"E","t":"Arthrodistension après anesthésie intra-articulaire","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2565, 20, 'Rhumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Quel est la physiopathologie de cette affection ?', '[{"l":"A","t":"Rupture tendineuse partielle","c":false},{"l":"B","t":"Bursite sous-acromiale","c":true},{"l":"C","t":"Conflit sous-acromial","c":true},{"l":"D","t":"Bursite à cristaux d''hydroxyapatite","c":true},{"l":"E","t":"Résorption d''une calcification tendineuse","c":true}]'::jsonb, 'Conseil du spécialiste : Bursite aiguë microcristalline = souvent « digestion » d''une caclification tendineuse à l''origine d''une bursite sous- acromiale à cristaux d''hydroxyapatite.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2566, 20, 'Rhumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Monsieur D. vous est très reconnaissant, mais il semble inquiet par la possibilité d''une rupture de la coiffe des rotateurs : «j''ai lu ça sur internet, ce n''est pas la peine de me cacher la vérité docteur». Quels signes cliniques retrouvez-vous en cas de rupture du sous-scapulaire?', '[{"l":"A","t":"Diminution de la mobilité passive en rotation interne","c":false},{"l":"B","t":"Douleurs à la mobilité active en rotation interne","c":false},{"l":"C","t":"Amyothrophie de la fosse infra-épineuse","c":false},{"l":"D","t":"Ressaut à 45° d''abduction","c":false},{"l":"E","t":"Diminution de la force au test de Geber","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2567, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Quels signes radiologiques sont très fréquemment associés à une rupture transfixiante de la coiffe des rotateurs?', '[{"l":"A","t":"Élargissement de l''espace acromio-huméral","c":false},{"l":"B","t":"Tête humérale ascensionnée","c":true},{"l":"C","t":"Arthrose gléna-humérale","c":true},{"l":"D","t":"Calcifications tendineuses","c":true},{"l":"E","t":"Luxation antérieure en cliché dynamique de Leclerc","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2568, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Monsieur O. revient pour douleur de l''hallux gauche et fièvre. Celui-ci est inflammatoire sans porte d''entrée infectieuse évidente. Les douleurs sont insomniantes. Vous suspectez un premier épisode de goutte. Vous faites une ponction articulaire qui confirme le diagnostic. Elle retrouve :', '[{"l":"A","t":"Cellularité > 2 OOO/mm 3","c":true},{"l":"B","t":"Quelques PNN altérés","c":true},{"l":"C","t":"Des microcristaux sensibles à l''EDTA","c":false},{"l":"D","t":"Des microcristaux courts, fins et pointus","c":false},{"l":"E","t":"Des microcristaux biréfringents en lumière polarisée","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2569, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Quel est votre traitement ?', '[{"l":"A","t":"Bandage compressif contre l''œdème","c":false},{"l":"B","t":"Décharge du membre","c":true},{"l":"C","t":"Colchicine","c":true},{"l":"D","t":"Allopurinol","c":false},{"l":"E","t":"Rasburicase","c":false}]'::jsonb, 'Conseil du spécialiste : Traitement de fond hypo-uricémiant seulement en cas de deuxième épisode, de complications rénales ou d''arthropathie chronique.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2570, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Vous êtes orthopédiste en ville. Monsieur O., un quinquagénaire féru de golf vous est adressé par son médecin traitant pour des douleurs du coude droit apparues depuis peu. Il a l''air très informé et vous parle tout de suite d''un golf-elbow: « d''ailleurs docteur ça ne m''étonne pas depuis quelques mois je m''entraîne pour la compétition de l''année ». Il a comme antécédents, une HTA bien contrôlée, un ulcère gastro-duodénal en cours de traitement par /PP et une hypertrophie bénigne de la prostate peu symptomatique.', false, true, 'Votre patient est très inquiet des possibles effets secondaires de ce traitement, que lui répondez-vous ?', '[{"l":"A","t":"Troubles digestifs à type de constipation","c":false},{"l":"B","t":"Absence d''effet secondaire grave","c":false},{"l":"C","t":"Éruption cutanée","c":true},{"l":"D","t":"Crise de goutte à l''instauration du traitement","c":false},{"l":"E","t":"Consultation en cas de diarrhée inhabituelle","c":true}]'::jsonb, 'Conseil du spécialiste : Effets secondaires de la colchicine = diarrhée +++ et plus rarement, leucopénie, rhabdomyolyse ..', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2571, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'Quelle déformation attendez-vous s''il s''agit d''une fracture de l''extrémité distale du radius de type Pouteau- Colles?', '[{"l":"A","t":"Horizontalisation de la ligne bi-styloïdienne","c":true},{"l":"B","t":"Ventre de fourchette","c":false},{"l":"C","t":"Main botte radiale","c":true},{"l":"D","t":"Saillie de la styloïde radiale","c":false},{"l":"E","t":"Signe de l''épaulette","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2572, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'Quel est l''aspect normal d''une radiographie du poignet ?', '[{"l":"A","t":"Index radio-ulnaire le plus souvent négatif","c":true},{"l":"B","t":"Inclinaison palmaire de la glène radiale","c":true},{"l":"C","t":"Capitatum, lunatum et radius alignés sur le profil","c":true},{"l":"D","t":"Diastasis radio-ulnaire distal","c":false},{"l":"E","t":"Inclinaison de la surface articulaire distale du radius de 5° environ par rapport à son grand axe dans le plan frontal","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2573, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'Quels types de traumatisme sont le plus probablement responsables de la fracture de cette patiente ?', '[{"l":"A","t":"Compression","c":true},{"l":"B","t":"Hyperextension","c":false},{"l":"C","t":"Hyperflexion","c":true},{"l":"D","t":"Varus","c":false},{"l":"E","t":"Valgus","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2574, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'Quel est le traitement ?', '[{"l":"A","t":"Réduction en urgence par manœuvre externe aux urgences","c":false},{"l":"B","t":"Ostéosynthése par embrochage per-cutané","c":true},{"l":"C","t":"Vis-plaque","c":false},{"l":"D","t":"Fixateur externe","c":false},{"l":"E","t":"Immobilisation par manchette","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2575, 3, 'Traumatologie', 'Principe de base en médecine physique et réadaptation', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'Quelle est votre conduite à tenir à moyen terme ?', '[{"l":"A","t":"Radiographies du poignet 1x/semaine jusqu''à la 6° semaine","c":false},{"l":"B","t":"Retrait du matériel d''ostéosynthèse au bloc opératoire","c":false},{"l":"C","t":"Consultations mensuelles au début","c":false},{"l":"D","t":"Retrait de l''immobilisation à 6 semaines environ","c":true},{"l":"E","t":"Prescription de kinésithérapie sans attendre","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2576, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'Vous redoutez un syndrome post-chute, quelles en sont les caractéristiques cliniques ?', '[{"l":"A","t":"Rétropulsion","c":true},{"l":"B","t":"Festination","c":true},{"l":"C","t":"Élargissement du polygone de sustentation","c":true},{"l":"D","t":"Démotivation","c":true},{"l":"E","t":"Régression psycho-motrice","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2577, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'Quel est votre bilan pour rechercher l''étiologie de cette chute?', '[{"l":"A","t":"ECG d''effort","c":false},{"l":"B","t":"Glycémie","c":true},{"l":"C","t":"TOM cérébrale","c":false},{"l":"D","t":"Recherche d''hypotension orthostatique","c":true},{"l":"E","t":"Dépistage des psychotropes dans les urines","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2578, 29, 'Rhumatologie', 'Algoneurodystrophie', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'La patiente consulte 8 semaines plus tard pour des douleurs du poignet gauche. La peau en regard vous semble luisante, les amplitudes articulaires sont diminuées. Les douleurs ont un horaire inflammatoire. Quelles sont les caractéristiques de ces douleurs si elles sont de type inflammatoire :', '[{"l":"A","t":"Douleurs en deuxième moitié de nuit","c":true},{"l":"B","t":"Dérouillage matinal > 30 min","c":true},{"l":"C","t":"Absence de réveil nocturne","c":false},{"l":"D","t":"Douleurs augmentées à la mobilisation","c":false},{"l":"E","t":"Douleurs abarticulaires","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2579, 29, 'Rhumatologie', 'Algoneurodystrophie', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'Quel élément déterminant manque dans votre examen ?', '[{"l":"A","t":"Recherche d''un retentissement fonctionnel","c":false},{"l":"B","t":"Prise de température","c":true},{"l":"C","t":"Recherche d''une hypersudation","c":false},{"l":"D","t":"Recherche d''épisodes douloureux similaires","c":false},{"l":"E","t":"Examen de l''articulation controlatérale","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2580, 21, 'Rhumatologie', 'Arthrite septique', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'Cet élément est normal, quel est alors votre diagnostic principal?', '[{"l":"A","t":"Arthrite septique","c":false},{"l":"B","t":"Pseudarthrose septique","c":false},{"l":"C","t":"Syndrome douloureux régional complexe","c":true},{"l":"D","t":"Algodystrophie en phase pseudo-ischémique","c":false},{"l":"E","t":"Douleurs normales à distance de la chirurgie","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2581, 29, 'Rhumatologie', 'Algoneurodystrophie', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'Vous prescrivez un bilan paraclinique. Quels sont les résultats compatibles avec votre hypothèse ?', '[{"l":"A","t":"VS augmentée","c":false},{"l":"B","t":"Radiographie du poignet normale","c":true},{"l":"C","t":"Hypertransparence osseuse sous-chondrale","c":true},{"l":"D","t":"Hypersignal T2 osseux à l''IRM","c":true},{"l":"E","t":"Hypofixation au temps précoce de la scintigraphie osseuse","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2582, 29, 'Rhumatologie', 'Algoneurodystrophie', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'Quels traitements pouvez-vous prescrire ?', '[{"l":"A","t":"Attelle d''immobilisation","c":true},{"l":"B","t":"Calcitonine per os","c":false},{"l":"C","t":"Paracétamol 4 g par jour per os","c":true},{"l":"D","t":"Biphosphonates en première intention","c":false},{"l":"E","t":"Aucune de ces réponses","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2583, 29, 'Rhumatologie', 'Algoneurodystrophie', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'Quels sont les principes de la kinésithérapie dans cette pathologie ?', '[{"l":"A","t":"Débutée à distance de la phase chaude","c":false},{"l":"B","t":"Bains éccossais","c":true},{"l":"C","t":"Respect de l''indolence","c":true},{"l":"D","t":"Électro-stimulation","c":false},{"l":"E","t":"Arthrodistension","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2584, 29, 'Rhumatologie', 'Algoneurodystrophie', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'Quels éléments auraient permis de prévenir cette pathologie?', '[{"l":"A","t":"Analgésie post-opératoire satisfaisante","c":true},{"l":"B","t":"Soutien psychologique","c":true},{"l":"C","t":"Rééducation intensive","c":false},{"l":"D","t":"Immobilisation plus longue","c":false},{"l":"E","t":"Corticothérapie en cure courte","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2585, 29, 'Rhumatologie', 'Algoneurodystrophie', 'Une femme de 74 ans se présente aux urgences pour douleurs du poignet gauche suite à une chute de sa hauteur. Vous remarquez immédiatement une déformation sans signe d''ouverture cutanée. L''examen clinique est sans particularité par ailleurs.', false, true, 'La patiente souhaite avoir des informations sur cette pathologie. Que lui répondez-vous ?', '[{"l":"A","t":"Guérison compléte sans séquelle dans 60 % des cas","c":false},{"l":"B","t":"Possibilité de récidive sur la même articulation","c":true},{"l":"C","t":"Évolution possible sur plus d''un an","c":true},{"l":"D","t":"Mécanisme probablement multifactoriel","c":true},{"l":"E","t":"Guérison d''autant plus longue que l''intensité du traumatisme a été élevée","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2586, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'Quelles déformations du membre inférieur gauche auraient été dans le sens de votre intuition ?', '[{"l":"A","t":"Rotation interne","c":false},{"l":"B","t":"Raccourcissement","c":true},{"l":"C","t":"Abduction","c":false},{"l":"D","t":"Adduction","c":true},{"l":"E","t":"Rotation externe","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2587, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'Le bilan biologique est le suivant: Leucocytes : 8 000 I mm3, Hb : 12 g/dl, plaquettes : 200 000/mm3. Na+ : 136 mmol/I, K+: 5,6 mmol/I, Cl- : 98 mmol/I. Créatininémie : 200 µmoiti, urée plasmatique : 8 mmol/I. CPK : 7 000 Ul/I. Glycémie : 3 g/I. Ph : 7,25 PaC02 41 mmHg, HC03· = 18 mmHg Vous évoquez :', '[{"l":"A","t":"Une rhabdomyolyse","c":true},{"l":"B","t":"Une insuffisance rénale fonctionnelle","c":false},{"l":"C","t":"Une acidose à trou anionique normal","c":false},{"l":"D","t":"Une CIVD","c":false},{"l":"E","t":"Une pneumopathie d''inhalation","c":false}]'::jsonb, 'Conseil du spécialiste : la rhabdomyolyse entraîne une insuffisance rénale organique par pré-cipitation intra-tubulaire de myoglobine et une acidose métabolique à trou anionique augmenté.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2588, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'Quelle est votre conduite à tenir concernant le traitement de la fracture ?', '[{"l":"A","t":"Mise en traction et chirurgie différée","c":false},{"l":"B","t":"Réduction sous contrôle de la scopie","c":true},{"l":"C","t":"Traitement non-conservateur","c":false},{"l":"D","t":"Intervention chirurgicale dans les 24 h","c":true},{"l":"E","t":"Bilan pré-transfusionnel","c":true}]'::jsonb, 'Conseil du spécialiste : Traitement de la per-trochantérienne = Urgence I réduction I ostéosynthèse.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2589, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'Quels traitements chirurgicaux vous paraissent appropriés?', '[{"l":"A","t":"Vissage du col","c":false},{"l":"B","t":"Ostéosynthèse à foyer fermé","c":true},{"l":"C","t":"Enclouage médullaire","c":true},{"l":"D","t":"Ostéosynthèse à foyer ouvert","c":true},{"l":"E","t":"Vis-plaque","c":true}]'::jsonb, 'Conseil du spécialiste : Traitement de la per-trochantérienne = Urgence I réduction I ostéosynthèse.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2590, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'À propos de la reprise de l''appui :', '[{"l":"A","t":"Mise au fauteuil dès le lendemain de l''intervention","c":true},{"l":"B","t":"Appui plus précoce lors d''un traitement par ostéosynthèse qu''en cas d''arthroplastie.","c":false},{"l":"C","t":"Appui sans béquille dès J5 post-opératoire","c":false},{"l":"D","t":"Apprentissage des positions luxantes à ne pas réaliser","c":false},{"l":"E","t":"Appui sans béquille après retrait du matériel d''ostéo-synthèse","c":false}]'::jsonb, 'Conseil du spécialiste : Mise au fauteuil dès j1, reprise d''un appui partiel puis appui total si consolidation radiologique.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2591, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'Quelles sont les complications auxquelles vous vous attendez le plus ?', '[{"l":"A","t":"Ostéonécrose aseptique de la tête fémorale","c":false},{"l":"B","t":"Cotyloïdite","c":false},{"l":"C","t":"Cals vicieux","c":true},{"l":"D","t":"Débricollage du matériel d''ostéosynthèse","c":true},{"l":"E","t":"Hyperglycémie","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2592, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'Le taux de mortalité d''une fracture de l''extrémité supérieure du fémur :', '[{"l":"A","t":"Est indépendant du type de fracture","c":false},{"l":"B","t":"Dépend de l''âge du patient","c":true},{"l":"C","t":"Est inférieur à 10 %","c":false},{"l":"D","t":"Peut-être supérieur à 30 %","c":true},{"l":"E","t":"Dépend de la verticalité du trait de fracture dans les fractures cervicales","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2593, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'Quel est le bilan biologique que vous réalisez dans le cadre d''un diagnostic d''ostéoporose ?', '[{"l":"A","t":"Dosage de la 25-0H vitamine 03","c":true},{"l":"B","t":"NFS","c":true},{"l":"C","t":"EPP","c":true},{"l":"D","t":"Bilan phosphocalcique","c":true},{"l":"E","t":"VS-CRP","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2594, 31, 'Rhumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'À propos des indications de l''ostéodensitométrie :', '[{"l":"A","t":"Elle est indiquée chez cette patiente car elle a présenté une fracture du col du fémur sans traumatisme sévére","c":true},{"l":"B","t":"Elle est indiquée en cas d''hyperthyroïdie non traitée","c":true},{"l":"C","t":"Elle est indiquée chez les femmes ayant un IMC < 19","c":false},{"l":"D","t":"Elle est indiquée dans la population générale en cas d''ATCD de fracture du col sans traumatisme majeur, au premier degré","c":false},{"l":"E","t":"Elle est indiquée chez les hommes traités par analogue de la GNRH","c":true}]'::jsonb, 'Conseil du spécialiste : Tout est dans les fiches HAS +++.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2595, 2, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'Vous parlez à la patiente d''un outil d''aide à l''évaluation du risque fracturaire : FRAX. Quels sont les items qui y figurent?', '[{"l":"A","t":"Prise de 3 doses d''OH ou plus","c":true},{"l":"B","t":"Poids et taille","c":true},{"l":"C","t":"Âge","c":true},{"l":"D","t":"Tabagisme","c":true},{"l":"E","t":"Antécédent de polyarthrite rhumatoïde","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2596, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'Prescrivez-vous un traitement anti-ostéoporotique à cette patiente ?', '[{"l":"A","t":"Oui seulement si le T-score < -2,5 OS","c":false},{"l":"B","t":"Seulement en fonction de l''outil FRAX si T-score > -2,50S","c":false},{"l":"C","t":"Jamais si T-score > -1 OS","c":false},{"l":"D","t":"Oui même en absence d''ostéodensitométrie","c":false},{"l":"E","t":"Oui si T-score < -1 OS","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2597, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'Quels facteurs vont influencer le choix du médicament ?', '[{"l":"A","t":"Le site de la fracture","c":true},{"l":"B","t":"La créatininémie","c":true},{"l":"C","t":"Un antécédent d''embolie pulmonaire","c":true},{"l":"D","t":"Un antécédent de cancer ORL","c":true},{"l":"E","t":"La calcémie","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2598, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'Quel suivi proposez-vous à cette patiente concernant son ostéoporose ?', '[{"l":"A","t":"Ostéodensitométrie à l''arrêt du traitement","c":true},{"l":"B","t":"Ostéodensitométrie si arrêt précoce pour effet secondaire","c":false},{"l":"C","t":"Ostéodensitométrie avant de faire le relais du Tériparatide pour un Biphosphonate","c":true},{"l":"D","t":"Radiographies de hanche et du rachis lombaire","c":false},{"l":"E","t":"Mesures régulières de la taille","c":true}]'::jsonb, 'Conseil du spécialiste : Tout est dans les fiches HAS +++.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2599, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Madame E., 75 ans, vous attend dans le box des urgences pour douleurs inguinales gauches apparues depuis une chute de sa hauteur. Elle a passé un temps important au sol. Elle a dans ses antécédents un diabète de type 2 bien équilibré sous insuline. Vous évoquez de principe une fracture de l''extrémité supérieure du fémur.', false, true, 'Madame E. vous questionne à propos de son ostéoporose:', '[{"l":"A","t":"Il s''agit d''une ostéoporose post-ménopausiques","c":true},{"l":"B","t":"Il s''agit d''une ostéoporose par carence œstrogénique","c":true},{"l":"C","t":"Arrêter de fumer diminue son risque fracturaire","c":true},{"l":"D","t":"La masse osseuse atteint son pic à 50 ans et diminue ensuite avec l''âge","c":false},{"l":"E","t":"Un traitement hormonal substitutif aurait pu être prescrit pour éviter l''ostéoporose","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2600, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', ':2 1 Madame M., 80 ans est amenée aux urgences par son fils pour des douleurs de la hanche droite depuis qu''elle a chuté la veille dans son salon en se prenant les pieds dans Je chat. C''est son voisin qui l''a retrouvé au sol en venant lui apporter le pain. La patiente est peu algique, mais vous semble confuse. Le membre inférieur droit n''est pas déformé. Madame M. parvient à marcher à J''aide de sa canne. Elle a comme antécédents: une ACFA sous AVK (objectif INR = 3) et une hypothyroïdie bien substituée. Vous évoquez une lésion osseuse post-traumatique du membre supérieur.', false, true, 'Quels sont alors les types de fracture que vous évoquez ?', '[{"l":"A","t":"Fracture cervicale en coxa valga","c":true},{"l":"B","t":"Fracture cervicale en coxa vara","c":false},{"l":"C","t":"Fracture du cadre obturateur","c":true},{"l":"D","t":"Fracture per-trochantérienne simple","c":false}]'::jsonb, 'Conseil du spécialiste : Devant un patient qui peut marcher, évoquez les fractures du cadre obturateur, les garden 1et Il.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2601, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', ':2 1 Madame M., 80 ans est amenée aux urgences par son fils pour des douleurs de la hanche droite depuis qu''elle a chuté la veille dans son salon en se prenant les pieds dans Je chat. C''est son voisin qui l''a retrouvé au sol en venant lui apporter le pain. La patiente est peu algique, mais vous semble confuse. Le membre inférieur droit n''est pas déformé. Madame M. parvient à marcher à J''aide de sa canne. Elle a comme antécédents: une ACFA sous AVK (objectif INR = 3) et une hypothyroïdie bien substituée. Vous évoquez une lésion osseuse post-traumatique du membre supérieur.', false, true, 'Quels éléments d''interrogatoire et cliniques vous paraissent indispensables à recueillir ?', '[{"l":"A","t":"La notion de prise d''antiagrégants plaquettaires","c":true},{"l":"B","t":"La présence de fièvre","c":true},{"l":"C","t":"L''autonomie de la patiente","c":true},{"l":"D","t":"La notion de perte de connaissance","c":true},{"l":"E","t":"La notion de traumatisme crânien","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
